// Map of Tomorrow analytics worker.
// build-stamp: studio-v1 (posts + media + sync)
//
// Two responsibilities:
//   1. Authenticate to the Google Analytics Data API using a service-account
//      JWT (because the API rejects api-key auth — that's the 401 we kept
//      hitting). The dashboard at analytics.html keeps its existing call
//      shape and routes through here.
//   2. Receive identified-user events from index.html and persist them to
//      Cloudflare D1. Then serve dashboard queries (people list, member
//      timelines, watchlist rankings, activity feed) over those rows.
//
// Why a service account and not OAuth2 user auth?
//   Workers are server-side; there's no human present to consent. The service
//   account acts as a non-human principal granted read-only access to one
//   specific GA4 property. The README walks through the GCP-side setup.

import { handleMcp, autoPromoteOpenedProjects, recordArticleCoverage, syncOpenDeliveryDates } from './mcp.js';
import { handleOAuth } from './oauth.js';
import { handleGallery } from './gallery.js';
import { ONTOLOGY, ONTOLOGY_VERSION, ontologyText } from './ontology.js';
import { TRAVEL_STOPS } from './travel-data.js';

// ---------------------------------------------------------------------------
// CORS helpers
// ---------------------------------------------------------------------------

function corsHeaders(env, origin) {
  const allowList = (env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
  // Echo the origin back if it's allowed, otherwise fall back to the canonical
  // primary origin (so requests from curl / Postman that don't send Origin
  // still work). We deliberately never emit '*' here: a disallowed browser
  // origin will see an ACAO that doesn't match its own origin and the browser
  // will block the response, which is the behavior we want. (Auth, not CORS,
  // is the real access control — see requireAdminToken on the read endpoints.)
  const ok = allowList.includes(origin)
    || /^https:\/\/([a-z0-9-]+\.)*pages\.dev$/i.test(origin)   // Cloudflare Pages previews + deploys
    || /^https:\/\/([a-z0-9-]+\.)*oftmw\.com$/i.test(origin);  // any oftmw.com subdomain
  const allow = ok ? origin : (allowList[0] || 'https://map.oftmw.com');
  return {
    'Access-Control-Allow-Origin': allow,
    'Access-Control-Allow-Methods': 'GET,POST,PATCH,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Authorization,Content-Type,X-Ingest-Token',
    'Access-Control-Max-Age': '86400',
    'Vary': 'Origin',
  };
}

function json(body, init = {}, env, origin) {
  return new Response(JSON.stringify(body), {
    status: init.status || 200,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...corsHeaders(env, origin),
      ...(init.headers || {}),
    },
  });
}

// ---------------------------------------------------------------------------
// Google service-account JWT mint  →  OAuth2 access token  →  call GA4 Data API
// ---------------------------------------------------------------------------
//
// We sign a short JWT with the service account's RSA private key, exchange it
// at Google's token endpoint for a 1-hour bearer token, and cache that token
// in module-global state so we don't re-sign on every request inside the same
// Worker isolate. Workers reuse isolates across requests, so this cache is
// genuinely useful — typically 1 mint per ~50 minutes per region.

let _cachedToken = null;        // { token: string, expiresAt: number(ms) }

export async function getGoogleAccessToken(env) {
  const now = Date.now();
  if (_cachedToken && _cachedToken.expiresAt > now + 60_000) {
    return _cachedToken.token;
  }

  if (!env.GA_SERVICE_ACCOUNT_JSON) {
    throw new Error('GA_SERVICE_ACCOUNT_JSON secret is not set. Run `wrangler secret put GA_SERVICE_ACCOUNT_JSON`.');
  }

  let sa;
  try {
    sa = JSON.parse(env.GA_SERVICE_ACCOUNT_JSON);
  } catch (e) {
    throw new Error('GA_SERVICE_ACCOUNT_JSON is not valid JSON: ' + e.message);
  }
  if (!sa.client_email || !sa.private_key) {
    throw new Error('Service account JSON is missing client_email or private_key.');
  }

  const iat = Math.floor(now / 1000);
  const exp = iat + 3600;
  const header  = { alg: 'RS256', typ: 'JWT' };
  const payload = {
    iss:   sa.client_email,
    scope: 'https://www.googleapis.com/auth/analytics.readonly',
    aud:   'https://oauth2.googleapis.com/token',
    iat,
    exp,
  };

  const enc = (obj) => b64urlBytes(new TextEncoder().encode(JSON.stringify(obj)));
  const signingInput = enc(header) + '.' + enc(payload);

  const key = await importPkcs8(sa.private_key);
  const sigBuf = await crypto.subtle.sign(
    { name: 'RSASSA-PKCS1-v1_5' },
    key,
    new TextEncoder().encode(signingInput),
  );
  const jwt = signingInput + '.' + b64urlBytes(new Uint8Array(sigBuf));

  const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=' + jwt,
  });

  if (!tokenRes.ok) {
    const text = await tokenRes.text();
    throw new Error('Google token exchange failed (' + tokenRes.status + '): ' + text);
  }
  const tokenJson = await tokenRes.json();

  _cachedToken = {
    token: tokenJson.access_token,
    expiresAt: now + (tokenJson.expires_in * 1000),
  };
  return _cachedToken.token;
}

// PEM → CryptoKey for RS256 signing. Strips the BEGIN/END lines, base64-decodes
// the body, imports it as a PKCS#8 RSA private key.
async function importPkcs8(pemString) {
  const pemContents = pemString
    .replace(/-----BEGIN [^-]+-----/g, '')
    .replace(/-----END [^-]+-----/g, '')
    .replace(/\s+/g, '');
  const binaryDer = b64ToBytes(pemContents);
  return crypto.subtle.importKey(
    'pkcs8',
    binaryDer.buffer,
    { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
    false,
    ['sign'],
  );
}

function b64urlBytes(bytes) {
  let str = '';
  for (let i = 0; i < bytes.length; i++) str += String.fromCharCode(bytes[i]);
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ---------------------------------------------------------------------------
// Route handlers
// ---------------------------------------------------------------------------

// Back-compat with the existing analytics.html which does:
//   fetch(WORKER_URL, { method: 'POST', body: JSON.stringify({ endpoint: ':runReport', body: {...} }) })
//
// We forward to the GA4 Data API with a fresh bearer token. The `endpoint` is
// either ':runReport' or ':runRealtimeReport' — anything else is rejected so
// the worker can't be used to call arbitrary Google APIs.
async function handleGAProxy(req, env, origin) {
  // Admin-gated: this forwards arbitrary report queries to the GA4 Data API
  // using our service-account token. Unauthenticated, it was a public read
  // proxy for ALL of the property's analytics. Only analytics.html calls it,
  // and it now sends Authorization: Bearer <ADMIN_TOKEN>.
  const denied = await requireAdminToken(req, env, origin);
  if (denied) return denied;

  let body;
  try { body = await req.json(); } catch { return json({ error: 'Invalid JSON body' }, { status: 400 }, env, origin); }

  const allowedEndpoints = new Set([':runReport', ':runRealtimeReport']);
  if (!allowedEndpoints.has(body.endpoint)) {
    return json({ error: 'Unsupported endpoint: ' + body.endpoint }, { status: 400 }, env, origin);
  }

  let token;
  try { token = await getGoogleAccessToken(env); }
  catch (e) { return json({ error: e.message }, { status: 500 }, env, origin); }

  const url = `https://analyticsdata.googleapis.com/v1beta/properties/${env.GA4_PROPERTY_ID}${body.endpoint}`;
  const upstream = await fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + token,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body.body || {}),
  });
  const respText = await upstream.text();
  // Pass GA's response through verbatim, including its error shape, so the
  // dashboard's existing error display keeps working.
  return new Response(respText, {
    status: upstream.status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...corsHeaders(env, origin),
    },
  });
}

// POST /event — write one identified-user event row to D1.
//
// SECURITY NOTE: the X-Ingest-Token is sent by every visitor's browser
// (it ships in public index.html source), so it is NOT a real secret — treat
// it as a soft speed-bump against trivial scripted spam, not as auth. Two
// things make this acceptable:
//   1. Blast radius is tiny. A forged request can only INSERT an analytics
//      row; it cannot read any member data — every read endpoint now requires
//      ADMIN_TOKEN (see requireAdminToken / ADMIN_READ_PATHS).
//   2. Defense-in-depth Origin check below rejects browser-based cross-site
//      forgery (it is best-effort: non-browser clients can omit/spoof Origin).
// If event spam ever becomes a real problem, add a Turnstile token or a
// per-IP/member rate limit (KV or Durable Object) rather than leaning on the
// shared token.
async function handleEventIngest(req, env, origin) {
  const headerToken = req.headers.get('X-Ingest-Token') || '';
  const tokenOk = !!env.EVENT_INGEST_TOKEN && headerToken === env.EVENT_INGEST_TOKEN;

  // Accept EITHER a token-authenticated server post OR a first-party browser
  // beacon (a trusted Origin). Browsers can't forge the Origin header, so a
  // trusted-origin request can only come from our own oftmw.com pages — that
  // lets the journal + media-kit identify logged-in members without shipping the
  // ingest secret into public JS. Server-to-server (blank Origin) needs the token.
  const reqOrigin = req.headers.get('Origin') || '';
  const allowList = (env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
  const originOk = !!reqOrigin && (allowList.includes(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*pages\.dev$/i.test(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*oftmw\.com$/i.test(reqOrigin));

  if (!tokenOk && !originOk) {
    return json({ error: 'unauthorized' }, { status: 401 }, env, origin);
  }

  let body;
  try { body = await req.json(); } catch { return json({ error: 'Invalid JSON body' }, { status: 400 }, env, origin); }

  if (!body.member_id || !body.event_name) {
    return json({ error: 'member_id and event_name are required' }, { status: 400 }, env, origin);
  }

  // Cloudflare auto-populates request.cf on incoming requests with the visitor's
  // edge-derived geography. Merge those into the event's props so the Studio
  // can display "Brooklyn, NY, US" on each activity row without a separate IP
  // lookup. Best-effort: cf can be absent during local dev / preview.
  const cf = req.cf || {};
  const geoProps = {};
  if (cf.city) geoProps.city = String(cf.city).slice(0, 60);
  if (cf.region) geoProps.region = String(cf.region).slice(0, 60);
  if (cf.regionCode) geoProps.regionCode = String(cf.regionCode).slice(0, 8);
  if (cf.country) geoProps.country = String(cf.country).slice(0, 4);
  const mergedProps = (body.props || Object.keys(geoProps).length) ? { ...(body.props || {}), ...geoProps } : null;

  const nowSec = Math.floor(Date.now() / 1000);
  try {
    await env.DB.prepare(
      `INSERT INTO events
       (ts, client_ts, member_id, email, member_name, plan, event_name,
        session_id, path, referrer, user_agent, props_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      nowSec,
      body.client_ts || null,
      String(body.member_id),
      body.email || null,
      body.member_name || null,
      body.plan || null,
      String(body.event_name),
      body.session_id || null,
      body.path || null,
      body.referrer || null,
      req.headers.get('User-Agent') || null,
      mergedProps ? JSON.stringify(mergedProps) : null,
    ).run();
  } catch (e) {
    return json({ error: 'DB insert failed: ' + e.message }, { status: 500 }, env, origin);
  }

  return json({ ok: true }, {}, env, origin);
}

// /intel-thread — device-to-device TMW Intelligence chat resume for logged-in
// members. GET ?member_id=mem_… returns the saved conversation; POST { member_id,
// qs:[…], turns:[{q,a,g}…] } upserts it. First-party only (trusted Origin, same
// gate as /event); only real Memberstack accounts (mem_*) get a row, so anon/bot
// traffic never writes. Turns carry the ANSWER (a) and grounding receipts (g)
// alongside each query so a resume renders instantly instead of re-querying the
// LLM for every restored turn — the old queries-only format replayed the whole
// thread through /smart-answer on every return visit. Old rows (bare query
// array) and old clients (qs-only POST) still work.
async function handleIntelThread(request, env, origin, url) {
  const reqOrigin = request.headers.get('Origin') || '';
  const allowList = (env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
  const originOk = !!reqOrigin && (allowList.includes(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*pages\.dev$/i.test(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*oftmw\.com$/i.test(reqOrigin));
  if (!originOk) return json({ error: 'unauthorized' }, { status: 401 }, env, origin);

  try { await env.DB.prepare('CREATE TABLE IF NOT EXISTS intel_threads (member_id TEXT PRIMARY KEY, thread_json TEXT, updated_at INTEGER)').run(); } catch (_) {}

  // One turn = { q: query, a: answer prose | null, g: grounding {p,a,place} | null }.
  const sanitizeTurns = (arr) => (Array.isArray(arr) ? arr : [])
    .filter(t => t && typeof t.q === 'string' && t.q.trim())
    .map(t => ({
      q: t.q.slice(0, 200),
      a: (typeof t.a === 'string' && t.a.trim()) ? t.a.slice(0, 8000) : null,
      g: (t.g && typeof t.g === 'object')
        ? { p: Math.max(0, +t.g.p || 0), a: Math.max(0, +t.g.a || 0), place: typeof t.g.place === 'string' ? t.g.place.slice(0, 80) : null }
        : null,
    }))
    .slice(-12);

  if (request.method === 'GET') {
    const memberId = url.searchParams.get('member_id') || '';
    if (memberId.indexOf('mem_') !== 0) return json({ ok: true, qs: [], turns: [], ts: 0 }, {}, env, origin);
    let row = null;
    try { row = await env.DB.prepare('SELECT thread_json, updated_at FROM intel_threads WHERE member_id = ?').bind(memberId).first(); } catch (_) {}
    let qs = [], turns = [];
    try {
      if (row && row.thread_json) {
        const parsed = JSON.parse(row.thread_json);
        if (Array.isArray(parsed)) { qs = parsed; }                        // legacy: bare query list
        else if (parsed && typeof parsed === 'object') {
          turns = sanitizeTurns(parsed.turns);
          qs = turns.length ? turns.map(t => t.q) : (Array.isArray(parsed.qs) ? parsed.qs : []);
        }
      }
    } catch (_) {}
    return json({ ok: true, qs, turns, ts: (row && row.updated_at) || 0 }, {}, env, origin);
  }

  // POST — upsert (last write wins; the most-recently-active device is truth).
  let body; try { body = await request.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const memberId = String(body.member_id || '');
  if (memberId.indexOf('mem_') !== 0) return json({ ok: true, skipped: 'not a member account' }, {}, env, origin);
  const turns = sanitizeTurns(body.turns);
  const qs = turns.length ? turns.map(t => t.q)
    : (Array.isArray(body.qs) ? body.qs.filter(q => typeof q === 'string' && q.trim()).map(q => q.slice(0, 200)).slice(-12) : []);
  const ts = Date.now();
  try {
    if (qs.length) {
      const payload = JSON.stringify({ qs, turns });
      await env.DB.prepare('INSERT OR REPLACE INTO intel_threads (member_id, thread_json, updated_at) VALUES (?,?,?)').bind(memberId, payload, ts).run();
    } else {
      await env.DB.prepare('DELETE FROM intel_threads WHERE member_id = ?').bind(memberId).run();
    }
  } catch (e) { return json({ error: 'db: ' + e.message }, { status: 500 }, env, origin); }
  return json({ ok: true, ts }, {}, env, origin);
}

// ═══════════════════════════════════════════════════════════════════════════
// THE PASSPORT — member "I've been" check-ins on the iconic lists (golf, hotels,
// restaurants) + per-category and overall leaderboards. Consumer gamification,
// NOT Atlas market data. Free + Pro members both. Same trust model as the rest
// of the member layer: first-party Origin only, and the member_id (mem_…) is
// client-asserted (no token crypto) — this is low-stakes vanity data, and the
// whole account layer already trusts the client-supplied id.
//
//   POST /checkin            { member_id, entity_type, list_slug, item_id,
//                              item_name?, item_location?, visited_on, note?,
//                              display_name?, remove? }  → toggle one check-in
//   GET  /checkins?member_id=mem_…                       → a member's passport
//   GET  /checkin-counts?list_slug=…[&me=mem_…]          → per-item counts + the
//                                                          community module rows
//   GET  /leaderboard?scope=golf|hotels|restaurants|overall[&me=mem_…][&limit=]
//   GET/POST /member-prefs   { member_id, display_name?, leaderboard_hidden? }
//
// visited_on is REQUIRED on a check-in (the one bit of friction that keeps the
// board feeling earned); it's stored as free text but sanitized to YYYY[-MM[-DD]].
// Leaderboards are public-by-default: everyone appears unless they've set
// leaderboard_hidden=1. We NEVER surface a member's email or raw id publicly —
// only their chosen display_name.
// ---------------------------------------------------------------------------

const CHECKIN_ENTITY_TYPES = ['golf', 'hotels', 'restaurants'];

function checkinFirstPartyOk(request, env) {
  const reqOrigin = request.headers.get('Origin') || '';
  const allowList = (env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
  return !!reqOrigin && (allowList.includes(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*pages\.dev$/i.test(reqOrigin)
    || /^https:\/\/([a-z0-9-]+\.)*oftmw\.com$/i.test(reqOrigin));
}

async function ensureCheckinTables(env) {
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS checkins (
    member_id TEXT NOT NULL, entity_type TEXT NOT NULL, list_slug TEXT NOT NULL,
    item_id TEXT NOT NULL, item_name TEXT, item_location TEXT,
    visited_on TEXT, note TEXT, created_at INTEGER,
    PRIMARY KEY (member_id, list_slug, item_id)
  )`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_checkins_item ON checkins(list_slug, item_id)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_checkins_type ON checkins(entity_type, member_id)`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS member_prefs (
    member_id TEXT PRIMARY KEY, display_name TEXT,
    leaderboard_hidden INTEGER DEFAULT 0, updated_at INTEGER
  )`).run();
}

// Sanitize a member's chosen leaderboard handle: strip markup/control chars, cap
// length, and never let a raw email leak through (fall back to the local part).
function sanitizeHandle(raw) {
  let s = String(raw || '').replace(/<[^>]*>/g, '').replace(/[\u0000-\u001f]/g, '').trim();
  if (/@[^\s@]+\.[^\s@]+/.test(s)) s = s.split('@')[0];   // looks like an email → local part only
  s = s.replace(/\s+/g, ' ').slice(0, 40).trim();
  return s;
}

// YYYY / YYYY-MM / YYYY-MM-DD only; anything else → ''.
function sanitizeVisitedOn(raw) {
  const s = String(raw || '').trim().slice(0, 10);
  return /^\d{4}(-\d{2}(-\d{2})?)?$/.test(s) ? s : '';
}

async function handleCheckinToggle(request, env, origin) {
  if (!checkinFirstPartyOk(request, env)) return json({ error: 'unauthorized' }, { status: 401 }, env, origin);
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  let body; try { body = await request.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const memberId = String(body.member_id || '');
  if (memberId.indexOf('mem_') !== 0) return json({ ok: true, skipped: 'not a member account' }, {}, env, origin);
  const entityType = String(body.entity_type || '').toLowerCase();
  if (!CHECKIN_ENTITY_TYPES.includes(entityType)) return json({ error: 'bad entity_type' }, { status: 400 }, env, origin);
  const listSlug = String(body.list_slug || '').slice(0, 42);
  const itemId = String(body.item_id || '').slice(0, 80);
  if (!listSlug || !itemId) return json({ error: 'list_slug and item_id required' }, { status: 400 }, env, origin);

  await ensureCheckinTables(env);

  // Optional handle set alongside the first check-in (the confirm-your-name moment).
  if (body.display_name != null) {
    const dn = sanitizeHandle(body.display_name);
    if (dn) {
      try {
        await env.DB.prepare(`INSERT INTO member_prefs (member_id, display_name, updated_at)
          VALUES (?1, ?2, ?3)
          ON CONFLICT(member_id) DO UPDATE SET display_name = ?2, updated_at = ?3`)
          .bind(memberId, dn, Date.now()).run();
      } catch (_) {}
    }
  }

  const remove = body.remove === true || body.remove === 'true';
  try {
    if (remove) {
      await env.DB.prepare('DELETE FROM checkins WHERE member_id=?1 AND list_slug=?2 AND item_id=?3')
        .bind(memberId, listSlug, itemId).run();
    } else {
      const visitedOn = sanitizeVisitedOn(body.visited_on);
      if (!visitedOn) return json({ error: 'visited_on required (YYYY, YYYY-MM or YYYY-MM-DD)' }, { status: 400 }, env, origin);
      const itemName = String(body.item_name || '').replace(/<[^>]*>/g, '').slice(0, 160);
      const itemLoc = String(body.item_location || '').replace(/<[^>]*>/g, '').slice(0, 160);
      const note = String(body.note || '').replace(/<[^>]*>/g, '').slice(0, 400);
      await env.DB.prepare(`INSERT INTO checkins
        (member_id, entity_type, list_slug, item_id, item_name, item_location, visited_on, note, created_at)
        VALUES (?1,?2,?3,?4,?5,?6,?7,?8,?9)
        ON CONFLICT(member_id, list_slug, item_id) DO UPDATE SET
          entity_type=?2, item_name=?5, item_location=?6, visited_on=?7, note=?8`)
        .bind(memberId, entityType, listSlug, itemId, itemName, itemLoc, visitedOn, note, Date.now()).run();
    }
  } catch (e) { return json({ error: 'db: ' + e.message }, { status: 500 }, env, origin); }

  // Return the fresh count for this item so the button can update its "N been" chip.
  let cnt = 0;
  try {
    const r = await env.DB.prepare('SELECT COUNT(*) AS c FROM checkins WHERE list_slug=?1 AND item_id=?2')
      .bind(listSlug, itemId).first();
    cnt = (r && r.c) || 0;
  } catch (_) {}
  return json({ ok: true, checked: !remove, count: cnt }, {}, env, origin);
}

async function handleCheckinsGet(env, origin, url) {
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  const memberId = url.searchParams.get('member_id') || '';
  if (memberId.indexOf('mem_') !== 0) return json({ ok: true, items: [], counts: {}, ranks: {}, prefs: null }, {}, env, origin);
  await ensureCheckinTables(env);

  let items = [];
  try {
    const rs = await env.DB.prepare(`SELECT entity_type, list_slug, item_id, item_name, item_location, visited_on, note, created_at
      FROM checkins WHERE member_id=?1 ORDER BY created_at DESC`).bind(memberId).all();
    items = (rs && rs.results) || [];
  } catch (_) {}

  const counts = { golf: 0, hotels: 0, restaurants: 0, overall: 0 };
  for (const it of items) { if (counts[it.entity_type] != null) counts[it.entity_type]++; counts.overall++; }

  // Rank per scope = 1 + (members with a strictly higher count in that scope).
  const ranks = {};
  for (const scope of ['golf', 'hotels', 'restaurants', 'overall']) {
    const mine = counts[scope];
    if (!mine) { ranks[scope] = null; continue; }
    try {
      const r = await env.DB.prepare(`SELECT COUNT(*) AS ahead FROM (
        SELECT member_id, COUNT(*) AS cnt FROM checkins
        WHERE (?1 = 'overall' OR entity_type = ?1) GROUP BY member_id HAVING cnt > ?2)`)
        .bind(scope, mine).first();
      ranks[scope] = ((r && r.ahead) || 0) + 1;
    } catch (_) { ranks[scope] = null; }
  }

  let prefs = null;
  try {
    const p = await env.DB.prepare('SELECT display_name, COALESCE(leaderboard_hidden,0) AS hidden FROM member_prefs WHERE member_id=?1')
      .bind(memberId).first();
    if (p) prefs = { display_name: p.display_name || '', hidden: !!p.hidden };
  } catch (_) {}

  return json({ ok: true, items, counts, ranks, prefs }, {}, env, origin);
}

async function handleCheckinCounts(env, origin, url) {
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  const listSlug = (url.searchParams.get('list_slug') || '').slice(0, 42);
  if (!listSlug) return json({ error: 'list_slug required' }, { status: 400 }, env, origin);
  const me = url.searchParams.get('me') || '';
  await ensureCheckinTables(env);

  const counts = {}; let mine = {}; let total = 0; let community = [];
  try {
    const rs = await env.DB.prepare('SELECT item_id, COUNT(*) AS c FROM checkins WHERE list_slug=?1 GROUP BY item_id').bind(listSlug).all();
    for (const r of ((rs && rs.results) || [])) counts[r.item_id] = r.c;
  } catch (_) {}
  try {
    const r = await env.DB.prepare('SELECT COUNT(DISTINCT member_id) AS m FROM checkins WHERE list_slug=?1').bind(listSlug).first();
    total = (r && r.m) || 0;
  } catch (_) {}
  // The current member's own set of checked item_ids on this list (to paint buttons).
  if (me.indexOf('mem_') === 0) {
    try {
      const rs = await env.DB.prepare('SELECT item_id FROM checkins WHERE list_slug=?1 AND member_id=?2').bind(listSlug, me).all();
      for (const r of ((rs && rs.results) || [])) mine[r.item_id] = true;
    } catch (_) {}
  }
  // Community module — top visible members on THIS list.
  try {
    const rs = await env.DB.prepare(`SELECT c.member_id AS mid, COUNT(*) AS cnt, p.display_name AS dn,
        COALESCE(p.leaderboard_hidden,0) AS hidden
      FROM checkins c LEFT JOIN member_prefs p ON p.member_id = c.member_id
      WHERE c.list_slug=?1 GROUP BY c.member_id HAVING hidden=0
      ORDER BY cnt DESC, MIN(c.created_at) ASC LIMIT 5`).bind(listSlug).all();
    community = ((rs && rs.results) || []).map((r, i) => ({ rank: i + 1, name: r.dn || 'TMW Member', count: r.cnt }));
  } catch (_) {}

  return json({ ok: true, counts, mine, total, community }, {}, env, origin);
}

// The Explorer XP cache. Recomputing each member's full XP live for a whole-board
// ranking would be far too heavy (a per-member events scan), so a throttled cron
// (maybeRefreshExplorerXp) precomputes it here and the board reads it cheaply.
async function ensureExplorerTable(env) {
  try {
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS member_xp (
      member_id TEXT PRIMARY KEY, display_name TEXT, xp INTEGER, level INTEGER,
      tier TEXT, places INTEGER, updated_at INTEGER)`).run();
  } catch (_) {}
}

async function handleLeaderboard(env, origin, url) {
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  let scope = (url.searchParams.get('scope') || 'overall').toLowerCase();
  const me = url.searchParams.get('me') || '';
  let limit = parseInt(url.searchParams.get('limit') || '20', 10);
  if (!(limit > 0) || limit > 100) limit = 20;

  // Explorer board — ranked by total XP (travel + on-site market study combined),
  // read from the precomputed member_xp cache. No raw mem_ id is ever returned.
  if (scope === 'explorer') {
    await ensureExplorerTable(env);
    let rows = [];
    try {
      const rs = await env.DB.prepare(`SELECT x.member_id AS mid, x.xp AS xp, x.level AS level,
          x.tier AS tier, x.places AS places, x.updated_at AS ua,
          COALESCE(p.display_name, x.display_name) AS dn, COALESCE(p.leaderboard_hidden,0) AS hidden
        FROM member_xp x LEFT JOIN member_prefs p ON p.member_id = x.member_id
        WHERE COALESCE(p.leaderboard_hidden,0)=0 AND x.xp > 0`).all();
      rows = (rs && rs.results) || [];
    } catch (_) {}
    const out = rows
      .sort((a, b) => (b.xp - a.xp) || (a.ua - b.ua))
      .slice(0, limit)
      .map((r, i) => ({
        rank: i + 1, name: r.dn || 'TMW Member', xp: r.xp || 0,
        level: r.level || 1, tier: r.tier || '', places: r.places || 0,
        is_me: !!(me && r.mid === me),
      }));
    return json({ ok: true, scope: 'explorer', rows: out }, { headers: { 'Cache-Control': 'public, max-age=30, s-maxage=60' } }, env, origin);
  }

  if (scope !== 'overall' && !CHECKIN_ENTITY_TYPES.includes(scope)) scope = 'overall';
  await ensureCheckinTables(env);

  // Pull every visible member with their full per-category breakdown, then rank
  // by the requested scope in JS. Returning the breakdown on each row lets the
  // Passport page expand a profile into golf/hotels/restaurants counts WITHOUT
  // exposing raw mem_ ids (which would weaken the client-asserted trust model).
  let all = [];
  try {
    const rs = await env.DB.prepare(`SELECT c.member_id AS mid, COUNT(*) AS total,
        SUM(CASE WHEN c.entity_type='golf' THEN 1 ELSE 0 END) AS golf,
        SUM(CASE WHEN c.entity_type='hotels' THEN 1 ELSE 0 END) AS hotels,
        SUM(CASE WHEN c.entity_type='restaurants' THEN 1 ELSE 0 END) AS restaurants,
        MIN(c.created_at) AS firstAt, p.display_name AS dn, COALESCE(p.leaderboard_hidden,0) AS hidden
      FROM checkins c LEFT JOIN member_prefs p ON p.member_id = c.member_id
      GROUP BY c.member_id HAVING hidden=0`).all();
    all = (rs && rs.results) || [];
  } catch (_) {}
  const scoreOf = (r) => (scope === 'overall' ? r.total : (r[scope] || 0));
  const rows = all
    .filter(r => scoreOf(r) > 0)
    .sort((a, b) => scoreOf(b) - scoreOf(a) || a.firstAt - b.firstAt)
    .slice(0, limit)
    .map((r, i) => ({
      rank: i + 1, name: r.dn || 'TMW Member', count: scoreOf(r), total: r.total,
      golf: r.golf, hotels: r.hotels, restaurants: r.restaurants,
      is_me: !!(me && r.mid === me),
    }));
  return json({ ok: true, scope, rows }, { headers: { 'Cache-Control': 'public, max-age=30, s-maxage=60' } }, env, origin);
}

async function handleMemberPrefs(request, env, origin, url) {
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  await ensureCheckinTables(env);
  if (request.method === 'GET') {
    const memberId = url.searchParams.get('member_id') || '';
    if (memberId.indexOf('mem_') !== 0) return json({ ok: true, prefs: null }, {}, env, origin);
    let prefs = null;
    try {
      const p = await env.DB.prepare('SELECT display_name, COALESCE(leaderboard_hidden,0) AS hidden FROM member_prefs WHERE member_id=?1').bind(memberId).first();
      if (p) prefs = { display_name: p.display_name || '', hidden: !!p.hidden };
    } catch (_) {}
    return json({ ok: true, prefs }, {}, env, origin);
  }
  if (!checkinFirstPartyOk(request, env)) return json({ error: 'unauthorized' }, { status: 401 }, env, origin);
  let body; try { body = await request.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const memberId = String(body.member_id || '');
  if (memberId.indexOf('mem_') !== 0) return json({ ok: true, skipped: 'not a member account' }, {}, env, origin);
  const dn = body.display_name != null ? sanitizeHandle(body.display_name) : null;
  const hidden = body.leaderboard_hidden != null ? (body.leaderboard_hidden ? 1 : 0) : null;
  try {
    const existing = await env.DB.prepare('SELECT display_name, COALESCE(leaderboard_hidden,0) AS hidden FROM member_prefs WHERE member_id=?1').bind(memberId).first();
    const nextDn = dn != null ? dn : (existing ? (existing.display_name || '') : '');
    const nextHidden = hidden != null ? hidden : (existing ? existing.hidden : 0);
    await env.DB.prepare(`INSERT INTO member_prefs (member_id, display_name, leaderboard_hidden, updated_at)
      VALUES (?1,?2,?3,?4) ON CONFLICT(member_id) DO UPDATE SET display_name=?2, leaderboard_hidden=?3, updated_at=?4`)
      .bind(memberId, nextDn, nextHidden, Date.now()).run();
  } catch (e) { return json({ error: 'db: ' + e.message }, { status: 500 }, env, origin); }
  return json({ ok: true, prefs: { display_name: dn != null ? dn : undefined, hidden: hidden != null ? !!hidden : undefined } }, {}, env, origin);
}

// ── Passport name sync ───────────────────────────────────────────────────────
// One source of truth for a member's name: their Memberstack profile. The
// leaderboard handle (member_prefs.display_name) is always derived from it as
// "First L." — so editing the name in the account tab OR manually in Memberstack
// propagates to the leaderboard. Three sync points: the account-tab save (client
// POSTs the fresh handle), every check-in (client sends the current handle), and
// this hourly cron (catches manual Memberstack/Studio edits with no site visit).

// Leaderboard handle from a Memberstack profile's customFields: "First L.".
function deriveLeaderboardName(cf) {
  cf = cf || {};
  const first = String(cf['first-name'] || '').trim();
  const last = String(cf['last-name'] || '').trim();
  if (first && last) return (first + ' ' + last.charAt(0).toUpperCase() + '.').slice(0, 40);
  if (first) return first.slice(0, 40);
  return '';
}

// Pull each check-in member's CURRENT Memberstack name and refresh their
// leaderboard handle. Never touches leaderboard_hidden (the privacy opt-out).
async function syncCheckinNames(env) {
  if (!env.MEMBERSTACK_SECRET_KEY || !env.DB) return { synced: 0 };
  await ensureCheckinTables(env);
  let ids = [];
  try {
    const rs = await env.DB.prepare('SELECT DISTINCT member_id FROM checkins').all();
    ids = ((rs && rs.results) || []).map(r => r.member_id).filter(id => id && String(id).indexOf('mem_') === 0);
  } catch (_) { return { synced: 0 }; }
  let synced = 0;
  for (const id of ids) {
    try {
      const r = await fetch(MS_API + '/members/' + encodeURIComponent(id), { headers: msHeaders(env) });
      if (!r.ok) continue;
      const j = await r.json();
      const m = j.data || j;
      const name = deriveLeaderboardName((m && m.customFields) || {});
      if (!name) continue;
      await env.DB.prepare(`INSERT INTO member_prefs (member_id, display_name, updated_at)
        VALUES (?1,?2,?3) ON CONFLICT(member_id) DO UPDATE SET display_name=?2, updated_at=?3`)
        .bind(id, name, Date.now()).run();
      synced++;
    } catch (_) {}
  }
  return { synced };
}

async function maybeSyncCheckinNames(env) {
  try {
    const last = parseInt(await metaGet(env, 'checkin_name_sync_last') || '0', 10) || 0;
    const now = Math.floor(Date.now() / 1000);
    if (now - last < 300) return;               // every ~5 min — catches manual Memberstack edits promptly
    await metaSet(env, 'checkin_name_sync_last', now);
    await syncCheckinNames(env);
  } catch (_) {}
}

// Explorer leaderboard: recompute a rolling batch of members' total XP into the
// member_xp cache. computeMemberGameStats is heavy (a per-member events scan), so
// we refresh the stalest N seats each pass — the whole base cycles through over a
// few minutes and self-heals. The board (scope=explorer) reads the cache cheaply.
async function refreshExplorerXpBatch(env, batch) {
  if (!env.DB) return { refreshed: 0 };
  await ensureExplorerTable(env);
  let ids = [];
  try {
    const rs = await env.DB.prepare(
      `SELECT m.member_id AS id FROM members m
       LEFT JOIN member_xp x ON x.member_id = m.member_id
       WHERE m.member_id LIKE 'mem_%'
       ORDER BY COALESCE(x.updated_at, 0) ASC
       LIMIT ?1`).bind(batch || 25).all();
    ids = ((rs && rs.results) || []).map(r => r.id).filter(Boolean);
  } catch (_) { return { refreshed: 0 }; }
  let n = 0;
  for (const id of ids) {
    try {
      const s = await computeMemberGameStats(env, id);
      let name = s.name || '';
      try {
        const p = await env.DB.prepare('SELECT display_name FROM member_prefs WHERE member_id=?1').bind(id).first();
        if (p && p.display_name) name = p.display_name;
      } catch (_) {}
      await env.DB.prepare(`INSERT INTO member_xp (member_id, display_name, xp, level, tier, places, updated_at)
        VALUES (?1,?2,?3,?4,?5,?6,?7)
        ON CONFLICT(member_id) DO UPDATE SET display_name=?2, xp=?3, level=?4, tier=?5, places=?6, updated_at=?7`)
        .bind(id, name, s.xp || 0, s.level || 1, s.tier || '', (s.stats && s.stats.places) || 0, Date.now()).run();
      n++;
    } catch (_) {}
  }
  return { refreshed: n };
}

async function maybeRefreshExplorerXp(env) {
  try {
    const now = Math.floor(Date.now() / 1000);
    const last = parseInt(await metaGet(env, 'explorer_xp_last') || '0', 10) || 0;
    if (now - last < 120) return;               // a batch every ~2 min
    await metaSet(env, 'explorer_xp_last', now);
    await refreshExplorerXpBatch(env, 25);
  } catch (_) {}
}

// One-time backfill: reconcile every opened project's delivery_date with the real
// opening date in its dossier. Runs once (flagged), then never again.
async function maybeBackfillOpenDeliveryDates(env) {
  try {
    if (await metaGet(env, 'open_delivery_backfill_v1') === '1') return;
    const r = await syncOpenDeliveryDates(env);
    if (r && r.ok) await metaSet(env, 'open_delivery_backfill_v1', '1');
  } catch (_) {}
}

// ── Topaz Gigapixel upscale proxy ───────────────────────────────────────────
// Admin-only (the Studio Design editor reaches it via /api/topaz/* with the
// admin token). The Topaz API key lives ONLY here as the TOPAZ_API_KEY secret —
// never shipped to the browser. Topaz's image API is async, so three sub-routes:
//   POST /topaz/enhance   (multipart: image + model/output_width/output_height) → {process_id, eta}
//   GET  /topaz/status?id=<process_id>  → {status}  ("Completed" when done)
//   GET  /topaz/download?id=<process_id> → streams the finished image bytes
async function handleTopazUpscale(request, env, origin, url) {
  const denied = await requireAdminToken(request, env, origin);
  if (denied) return denied;
  if (!env.TOPAZ_API_KEY) return json({ error: 'TOPAZ_API_KEY not set — add it as a worker secret (wrangler secret put TOPAZ_API_KEY).' }, { status: 503 }, env, origin);
  const TOPAZ = 'https://api.topazlabs.com/image/v1';
  const KEY = { 'X-API-Key': env.TOPAZ_API_KEY };
  const sub = url.pathname.replace(/^\/topaz\/?/, '');

  if (sub === 'enhance' && request.method === 'POST') {
    const ct = request.headers.get('Content-Type') || '';
    const out = new FormData();
    let model = 'Standard V2', outFmt = 'png', ow, oh;
    if (ct.indexOf('application/json') >= 0) {
      // Photo-only flow: the editor passes the photo's public URL — Topaz fetches
      // it directly (no byte upload, no browser CORS).
      let b = {}; try { b = await request.json(); } catch {}
      if (!b.source_url) return json({ error: 'source_url or an image file is required' }, { status: 400 }, env, origin);
      out.append('source_url', String(b.source_url));
      model = b.model || model; outFmt = b.output_format || outFmt; ow = b.output_width; oh = b.output_height;
    } else {
      let form;
      try { form = await request.formData(); } catch { return json({ error: 'expected multipart/form-data or JSON' }, { status: 400 }, env, origin); }
      const file = form.get('image');
      if (!file || typeof file === 'string') return json({ error: 'image file is required' }, { status: 400 }, env, origin);
      out.append('image', file, (file.name || 'export.png'));
      model = form.get('model') || model; outFmt = form.get('output_format') || outFmt;
      ow = form.get('output_width'); oh = form.get('output_height');
    }
    out.append('model', String(model));
    out.append('output_format', String(outFmt));
    if (ow) out.append('output_width', String(parseInt(ow, 10) || ''));
    if (oh) out.append('output_height', String(parseInt(oh, 10) || ''));
    let r;
    try { r = await fetch(TOPAZ + '/enhance/async', { method: 'POST', headers: KEY, body: out }); }
    catch (e) { return json({ error: 'topaz unreachable: ' + e.message }, { status: 502 }, env, origin); }
    const txt = await r.text(); let j = {}; try { j = JSON.parse(txt); } catch {}
    if (!r.ok) return json({ error: 'topaz enhance failed', http: r.status, detail: (j && (j.detail || j.error)) || txt.slice(0, 300) }, { status: 502 }, env, origin);
    return json({ ok: true, process_id: j.process_id, eta: j.eta }, {}, env, origin);
  }

  if (sub === 'status' && request.method === 'GET') {
    const id = url.searchParams.get('id') || '';
    if (!id) return json({ error: 'id required' }, { status: 400 }, env, origin);
    let r; try { r = await fetch(TOPAZ + '/status/' + encodeURIComponent(id), { headers: KEY }); }
    catch (e) { return json({ error: 'topaz unreachable: ' + e.message }, { status: 502 }, env, origin); }
    const j = await r.json().catch(() => ({}));
    return json({ ok: r.ok, status: j.status || null, progress: j.progress, eta: j.eta }, { status: r.ok ? 200 : 502 }, env, origin);
  }

  if (sub === 'download' && request.method === 'GET') {
    const id = url.searchParams.get('id') || '';
    if (!id) return json({ error: 'id required' }, { status: 400 }, env, origin);
    let r; try { r = await fetch(TOPAZ + '/download/' + encodeURIComponent(id), { headers: KEY }); }
    catch (e) { return json({ error: 'topaz unreachable: ' + e.message }, { status: 502 }, env, origin); }
    const j = await r.json().catch(() => ({}));
    const durl = (j && (j.download_url || j.url)) || '';
    if (!r.ok || !durl) return json({ error: 'topaz download not ready', http: r.status }, { status: 502 }, env, origin);
    // Fetch the presigned URL server-side and stream the bytes back (no CORS,
    // and the editor never sees the temporary URL).
    let img; try { img = await fetch(durl); } catch (e) { return json({ error: 'presigned fetch failed: ' + e.message }, { status: 502 }, env, origin); }
    if (!img.ok) return json({ error: 'presigned fetch failed', http: img.status }, { status: 502 }, env, origin);
    return new Response(img.body, {
      status: 200,
      headers: { 'Content-Type': img.headers.get('Content-Type') || 'image/png', 'Cache-Control': 'no-store', ...corsHeaders(env, origin) },
    });
  }

  return json({ error: 'unknown topaz route' }, { status: 404 }, env, origin);
}

// GET /people — list of identified members, most recently active first.
// Returns rich per-member stats (sessions, active_days) computed from the
// raw events table. Cheap at low volume; if rows ever exceed ~10k we'd
// move sessions/active_days to a precomputed table.
export async function handlePeople(env, origin, url) {
  // Self-heal the registry: drop any non-Memberstack rows (system:* telemetry,
  // anon, bots) that were holding founding numbers, so this view never shows a
  // fake member with a seat.
  try { await ensureMembersTable(env); } catch (_) {}
  const rs = await env.DB.prepare(
    `SELECT member_id, email, member_name, plan, ts
     FROM events
     ORDER BY member_id ASC, ts DESC`
  ).all();

  // Walk rows, group by member, compute stats in one pass.
  const members = new Map();
  for (const row of (rs.results || [])) {
    // `system:*` ids are internal telemetry markers (system:smart-answer,
    // system:tmw-project-discovery, …), not people — keep them out of the roster.
    if (row.member_id && String(row.member_id).indexOf('system:') === 0) continue;
    let m = members.get(row.member_id);
    if (!m) {
      m = { member_id: row.member_id, email: null, member_name: null, plan: null, timestamps: [] };
      members.set(row.member_id, m);
    }
    // Rows are member ASC + ts DESC, so the FIRST non-empty value we see for each
    // field is its most recent one. Take email/name/plan from the latest event
    // that actually carries them — server-side events (deep searches, credit
    // grants, routines) insert with these columns NULL, and letting a NULL latest
    // event blank out a paid member's plan is what dropped them from the roster.
    if (m.email == null && row.email) m.email = row.email;
    if (m.member_name == null && row.member_name) m.member_name = row.member_name;
    if (m.plan == null && row.plan) m.plan = row.plan;
    m.timestamps.push(row.ts);
  }

  // Trialing members (Stripe, one list call) — lets the People view split active
  // trials out of "paid" without touching per-event plan. Fails open (no trials).
  const trialingEmails = new Set();
  try {
    if (env.STRIPE_SECRET_KEY) {
      const subs = await stripeGet(env, '/subscriptions?status=trialing&limit=100&expand[]=data.customer');
      for (const s of (subs.data || [])) {
        const em = s.customer && s.customer.email;
        if (em) trialingEmails.add(String(em).trim().toLowerCase());
      }
    }
  } catch (_) {}

  const out = Array.from(members.values()).map(m => {
    const ts = m.timestamps; // already in DESC order
    const stats = computeMemberStats(ts);
    return {
      member_id: m.member_id,
      email: m.email,
      member_name: m.member_name,
      // An anon: id has no account, so it can't be paid — a stale "paid" here is a
      // pre-identification event (a paid member's page-views fired under an anon id
      // before Memberstack resolved them). Always classify anon ids as anon.
      plan: (String(m.member_id || '').indexOf('anon:') === 0) ? 'anon' : m.plan,
      trialing: !!(m.email && trialingEmails.has(String(m.email).trim().toLowerCase())),
      event_count: ts.length,
      last_seen_ts: ts[0],
      first_seen_ts: ts[ts.length - 1],
      sessions: stats.sessions,
      active_days: stats.activeDays,
    };
  }).sort((a, b) => b.last_seen_ts - a.last_seen_ts);

  return json({ rows: out }, {}, env, origin);
}

// Session boundary: 30 minutes of inactivity ends a session.
// Active day: distinct UTC day with at least one event.
// Both metrics expect timestamps in DESC order (newest first).
function computeMemberStats(timestampsDesc) {
  if (!timestampsDesc.length) return { sessions: 0, activeDays: 0 };
  const days = new Set();
  let sessions = 1;
  for (let i = 0; i < timestampsDesc.length; i++) {
    days.add(Math.floor(timestampsDesc[i] / 86400));
    if (i > 0 && (timestampsDesc[i - 1] - timestampsDesc[i]) > 1800) sessions++;
  }
  return { sessions, activeDays: days.size };
}

// GET /stats — high-level dashboard counters in one round trip.
// Powers the four hero cards at the top of the dashboard.
async function handleStats(env, origin) {
  const rs = await env.DB.prepare(
    `SELECT member_id, plan, ts, event_name FROM events`
  ).all();
  const rows = rs.results || [];

  const memberPlans = new Map(); // member_id -> latest known plan
  const nowSec = Math.floor(Date.now() / 1000);
  const day = 86400;
  let eventsToday = 0;
  let eventsLast7d = 0;
  let eventsPrev7d = 0;
  const activeMembers7d = new Set();

  // First pass: pick most-recent plan per member. Rows aren't sorted, so
  // we need to track timestamps to know which plan value is "latest."
  const planTs = new Map(); // member_id -> latest ts with a NON-NULL plan
  for (const r of rows) {
    // Only let events that actually carry a plan set it — server-side events
    // (deep searches, credit grants, routines) have plan NULL and must not blank
    // out a member's real plan (that dropped paid members from the counters).
    if (r.plan && (!planTs.has(r.member_id) || planTs.get(r.member_id) < r.ts)) {
      planTs.set(r.member_id, r.ts);
      memberPlans.set(r.member_id, r.plan);
    }
    const age = nowSec - r.ts;
    if (age < day) eventsToday++;
    if (age < 7 * day) { eventsLast7d++; activeMembers7d.add(r.member_id); }
    else if (age < 14 * day) eventsPrev7d++;
  }

  let paidMembers = 0, freeMembers = 0;
  for (const plan of memberPlans.values()) {
    if (plan === 'paid') paidMembers++;
    else freeMembers++;
  }

  // Active members in the last 5 minutes (replaces the GA4 realtime card,
  // which can't be filtered by hostname). This is identified-member only —
  // exactly what we want for a "who's on map.oftmw.com right now" signal
  // in a dashboard focused on logged-in users.
  const fiveMinAgo = nowSec - 300;
  const activeNow = new Set();
  for (const r of rows) {
    if (r.ts >= fiveMinAgo) activeNow.add(r.member_id);
  }

  // Use snapshot-aware computation (covers backlogged watchlists too).
  const perMember = await computeWatchlists(env);
  const activeProjects = new Set();
  let totalActive = 0;
  for (const m of perMember.values()) {
    totalActive += m.current.size;
    for (const p of m.current) activeProjects.add(p);
  }

  return json({
    members_total: memberPlans.size,
    members_paid: paidMembers,
    members_free: freeMembers,
    active_now: activeNow.size,
    active_members_7d: activeMembers7d.size,
    events_today: eventsToday,
    events_last_7d: eventsLast7d,
    events_prev_7d: eventsPrev7d,
    events_total: rows.length,
    watchlist_unique_projects: activeProjects.size,
    watchlist_total_active: totalActive,
  }, {}, env, origin);
}

// GET /trending-searches — the top Onyx search queries in the last 7 days, for
// the homepage "Trending Onyx searches" strip. Public + edge-cached 30 min;
// anonymized (query text + count only), excludes the system routines + junk.
export async function handleTrendingSearches(env, origin) {
  if (!env.DB) return json({ searches: [] }, {}, env, origin);
  const since = Math.floor(Date.now() / 1000) - 7 * 86400;
  const out = [];
  try {
    const rs = await env.DB.prepare(
      `SELECT TRIM(json_extract(props_json,'$.q')) AS q, COUNT(*) AS n
         FROM events
        WHERE event_name='intel_query' AND ts>=?
          AND member_id NOT LIKE 'system:%' AND member_id NOT LIKE 'funnel:%'
          AND member_id NOT LIKE 'test%' AND member_id NOT LIKE 'claude%' AND member_id NOT LIKE 'preview%'
          AND json_extract(props_json,'$.q') IS NOT NULL
        GROUP BY LOWER(TRIM(json_extract(props_json,'$.q')))
        ORDER BY n DESC LIMIT 30`
    ).bind(since).all();
    // ── Theme dedupe: the raw top-N is dominated by variants of the same ask
    // ("tallest towers coming to new york?" / "new projects coming to new york
    // city" / "what about new york?"). Keep ONE query per place, drop
    // "what about X?" follow-up fragments, near-dupe by token overlap, cap 5.
    const PLACES = [
      [/new york|nyc|manhattan|brooklyn/i, 'ny'], [/west palm|wpb/i, 'wpb'],
      [/miami|brickell|wynwood/i, 'mia'], [/palm beaches/i, 'pbc'],
      [/caribbean/i, 'car'], [/around the world|worldwide|global/i, 'world'],
      [/\busa\b|\bus\b|united states|america/i, 'usa'], [/florida\b/i, 'fl'],
      [/nashville/i, 'bna'], [/austin/i, 'atx'], [/boynton/i, 'boy'], [/delray/i, 'del'],
    ];
    const toks = (s) => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/)
      .filter((w) => w.length > 2 && !['the', 'and', 'for', 'new', 'what', 'whats', 'about', 'coming', 'opening', 'are', 'in'].includes(w));
    const placeOf = (q) => { for (const [re, key] of PLACES) if (re.test(q)) return key; return null; };
    const kept = [];
    const keep = (q, count) => {
      const p = placeOf(q);
      if (p && kept.some((k) => k.place === p)) return false;                 // one query per place
      const t = toks(q);
      if (kept.some((k) => (!p || !k.place || k.place === p) && t.filter((w) => k.toks.includes(w)).length >= Math.max(2, Math.ceil(t.length * 0.6)))) return false;  // near-dupe wording (same/no place only — "tallest towers" in two cities is two themes)
      kept.push({ q, count, place: p, toks: t });
      return true;
    };
    const rows = (rs.results || []).map((r) => ({ q: String(r.q || '').trim(), n: Number(r.n) || 0 }))
      .filter((r) => r.q.length >= 3 && r.q.length <= 64)
      .filter((r) => !/^(test|asdf+|hello|hi|hey|yo)$/i.test(r.q))
      .filter((r) => !/^what('?| i)?s? about /i.test(r.q))                     // follow-up fragments never trend
      .filter((r) => !/wisconsin/i.test(r.q));                                 // editorial exclude (Jake)
    // Curated picks (Jake): surface these themes when present in the log —
    // matched loosely so the REAL query text + count is what displays.
    const CURATED = [/tallest .*miami|miami.*tallest/i, /hotels? .*(usa|america|united states)/i];
    for (const re of CURATED) {
      const hit = rows.find((r) => re.test(r.q));
      if (hit) keep(hit.q, hit.n);
    }
    // Pinned (Jake): the Miami-tallest slot always shows — with the real query
    // text/count once anyone actually asks it (CURATED above wins the slot),
    // and this stand-in (count borrowed from the top live Miami ask) until then.
    if (!kept.some((k) => /tallest/i.test(k.q) && /miami/i.test(k.q))) {
      const mia = (rs.results || []).map((r) => ({ q: String(r.q || ''), n: Number(r.n) || 0 })).find((r) => /miami/i.test(r.q));
      keep('tallest towers coming to miami', (mia && mia.n) || 20);
    }
    for (const r of rows) { if (kept.length >= 5) break; keep(r.q, r.n); }
    kept.sort((a, b) => b.count - a.count);
    for (const k of kept.slice(0, 5)) out.push({ q: k.q, count: k.count });
  } catch { /* best-effort; empty strip hides itself */ }
  return json({ searches: out }, { headers: { 'Cache-Control': 'public, max-age=1800, s-maxage=1800' } }, env, origin);
}

// ---------------------------------------------------------------------------
// GET /subscriptions — Memberstack subscription analytics for the map
// dashboard's revenue tiles. Memberstack runs paid plans on top of Stripe and
// exposes an Admin REST API (base https://admin.memberstack.com, auth via the
// `X-API-KEY: sk_...` header). We pull every plan (for price + billing cadence)
// and every member (for active plan connections), then aggregate:
//   - paying / free subscriber counts
//   - monthly vs yearly active-subscription counts ("purchase tendencies")
//   - MRR (each active paid sub normalized to a monthly amount)
//   - all-time income — ESTIMATED. Memberstack's Admin API has no
//     transactions/invoices endpoint, so true historical revenue lives in
//     Stripe. We approximate lifetime billed from *current* paying members as
//     (monthly amount × months since the member was created). This excludes
//     churned members and is intentionally labeled an estimate in the UI.
//
// Requires the MEMBERSTACK_SECRET_KEY secret (wrangler secret put). When it's
// absent we return { configured:false } so the UI can show a setup hint rather
// than erroring. Field shapes vary across Memberstack accounts, so every read
// below is defensive; pass ?debug=1 to echo a raw plan + connection sample for
// calibration against live data.
// ---------------------------------------------------------------------------
const MS_API = 'https://admin.memberstack.com';

function msHeaders(env) {
  return { 'X-API-KEY': env.MEMBERSTACK_SECRET_KEY, 'Content-Type': 'application/json' };
}

// Normalize a money amount to major units (dollars). Memberstack usually
// reports amounts in major units already (e.g. 25 for $25), but some payloads
// use Stripe-style minor units (cents). Guard: treat a large whole number as
// cents only when it's an exact integer ≥ 1000 (i.e. ≥ $1000 would be unusual
// for a sub price but $10.00 = 1000 cents is common).
function msAmount(raw) {
  const n = Number(raw);
  if (!isFinite(n) || n <= 0) return 0;
  if (Number.isInteger(n) && n >= 1000) return n / 100;
  return n;
}

// Map any Memberstack interval representation to a per-month multiplier and a
// coarse 'monthly'|'yearly'|'other' bucket. Handles string ("MONTHLY"),
// nested ({ type:'month', count:1 }), and Stripe-ish ({ interval:'year' }).
// Derive billing cadence from a planConnection.payment object. Memberstack's
// payment object has NO interval field — the cadence lives in the priceId slug
// (e.g. "prc_annual-9i2e0eab", "prc_monthly-86u0uyc"). We parse that, and fall
// back to the gap between lastBillingDate/nextBillingDate (unix seconds) when
// the slug isn't descriptive. Returns a coarse bucket + a factor that converts
// the charge amount to a monthly-equivalent (for MRR).
function msPaymentCadence(payment) {
  const pid = String(payment.priceId || payment.priceName || payment.price || '').toLowerCase();
  if (/annual|yearly|year|yr|12mo/.test(pid)) return { bucket: 'yearly',  perMonthFactor: 1 / 12 };
  if (/month|monthly|\bmo\b|30day/.test(pid)) return { bucket: 'monthly', perMonthFactor: 1 };
  if (/quarter|3mo|90day/.test(pid))          return { bucket: 'other',   perMonthFactor: 1 / 3 };
  if (/week|weekly/.test(pid))                return { bucket: 'other',   perMonthFactor: 52 / 12 };
  // Fallback: infer from the spacing of the billing dates.
  const last = Number(payment.lastBillingDate), next = Number(payment.nextBillingDate);
  if (last && next && next > last) {
    const days = (next - last) / 86400;
    if (days > 300) return { bucket: 'yearly',  perMonthFactor: 1 / 12 };
    if (days > 75)  return { bucket: 'other',   perMonthFactor: 1 / 3 };
    if (days > 20)  return { bucket: 'monthly', perMonthFactor: 1 };
    return { bucket: 'other', perMonthFactor: 52 / 12 };
  }
  return { bucket: 'other', perMonthFactor: 0 };
}

async function msFetchAllMembers(env) {
  const out = [];
  let after = null, guard = 0;
  do {
    const u = new URL(`${MS_API}/members`);
    u.searchParams.set('limit', '100');
    if (after) u.searchParams.set('after', after);
    const r = await fetch(u.toString(), { headers: msHeaders(env) });
    if (!r.ok) throw new Error(`Memberstack /members ${r.status}: ${(await r.text()).slice(0, 200)}`);
    const body = await r.json();
    const data = body.data || body.members || (Array.isArray(body) ? body : []);
    out.push(...data);
    // Pagination shapes: { hasNextPage, endCursor } or { totalCount, ... }.
    after = body.hasNextPage ? (body.endCursor || body.lastKey || null) : null;
    if (!after && body.totalCount && out.length < body.totalCount && data.length) {
      after = data[data.length - 1]?.id || null; // best-effort cursor fallback
    }
  } while (after && ++guard < 200);
  return out;
}

// Set of every Memberstack member email (normalized), cached 120s so submit-
// time existence checks don't page the Admin API on each call. New signups
// self-heal within 2 min; the create-password step's 'exists' error is the
// final backstop.
async function msMemberEmailSet(env) {
  const cache = caches.default;
  const cacheKey = new Request('https://email-status.tmw.internal/ms-emails');
  try {
    const hit = await cache.match(cacheKey);
    if (hit) return new Set(await hit.json());
  } catch { /* fall through to refetch */ }
  const members = await msFetchAllMembers(env);
  // Admin-API member shape varies; check the known email locations so a schema
  // quirk doesn't silently empty the set (which would make every lookup miss).
  const emails = members
    .map(m => String(
      (m.auth && m.auth.email) || m.email ||
      (m.customFields && (m.customFields.email || m.customFields['email-address'])) || ''
    ).trim().toLowerCase())
    .filter(Boolean);
  try {
    await cache.put(cacheKey, new Response(JSON.stringify(emails), {
      headers: { 'Cache-Control': 'max-age=120', 'Content-Type': 'application/json' },
    }));
  } catch { /* best-effort cache */ }
  return new Set(emails);
}

// POST /email-status { email } -> { ok, account }. Lets every email-capture
// form recognize an address that already has a Memberstack account and route
// the visitor to LOGIN instead of re-subscribing the same email forever.
// Returns account-existence ONLY (a boolean) — no plan, name, or other PII.
// "Subscribed but no account yet" is a separate state the subscribe worker
// reports via already_subscribed. Fails OPEN (account:false) so a lookup error
// never blocks a genuine signup.
async function handleEmailStatus(request, env, origin) {
  if (!env.MEMBERSTACK_SECRET_KEY) return json({ ok: false, account: false, reason: 'unconfigured' }, {}, env, origin);
  let body = {};
  try { body = await request.json(); } catch { /* empty body */ }
  const email = String((body && body.email) || '').trim().toLowerCase();
  if (!email || email.indexOf('@') < 1) return json({ ok: false, account: false }, {}, env, origin);
  try {
    const set = await msMemberEmailSet(env);
    return json({ ok: true, account: set.has(email) }, {}, env, origin);
  } catch {
    return json({ ok: false, account: false }, {}, env, origin);
  }
}

// ── Stripe — authoritative income (Memberstack bills through Stripe) ──────────
// When STRIPE_SECRET_KEY is set we pull real money from Stripe instead of
// estimating: MRR from active subscriptions (annual plans amortized to a monthly
// figure so a $90/yr payer counts as $7.50/mo, not $90 this month), and actual
// collected revenue (all-time + this calendar year) from succeeded charges minus
// refunds. Requires a restricted Stripe key with read access to subscriptions +
// charges. Paginated; charge history is capped at 30 pages (3,000 charges).
async function stripeGet(env, path) {
  const r = await fetch('https://api.stripe.com/v1' + path, {
    headers: { Authorization: 'Bearer ' + env.STRIPE_SECRET_KEY },
  });
  if (!r.ok) throw new Error('Stripe ' + r.status + ': ' + (await r.text()).slice(0, 200));
  return r.json();
}
// Writes (cancel) need a key with write scope. Prefer STRIPE_WRITE_KEY so the
// analytics read key can stay read-only; fall back to STRIPE_SECRET_KEY.
function stripeWriteKey(env) { return env.STRIPE_WRITE_KEY || env.STRIPE_SECRET_KEY; }
async function stripePost(env, path, params) {
  const r = await fetch('https://api.stripe.com/v1' + path, {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + stripeWriteKey(env), 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(params || {}),
  });
  if (!r.ok) {
    const body = (await r.text()).slice(0, 300);
    if (r.status === 401 || r.status === 403) throw new Error('Stripe ' + r.status + ' — the Stripe key lacks write access to subscriptions. Grant the restricted key "Subscriptions: Write", or set a STRIPE_WRITE_KEY secret.');
    throw new Error('Stripe ' + r.status + ': ' + body);
  }
  return r.json();
}
// Find a member's current subscription (trialing/active preferred) by email.
async function findSubByEmail(env, email) {
  if (!env.STRIPE_SECRET_KEY || !email) return null;
  const custs = await stripeGet(env, '/customers?email=' + encodeURIComponent(email) + '&limit=10');
  for (const c of (custs.data || [])) {
    const subs = await stripeGet(env, '/subscriptions?customer=' + c.id + '&status=all&limit=20');
    const list = subs.data || [];
    const best = list.find(s => s.status === 'trialing' || s.status === 'active') || list[0];
    if (best) return best;
  }
  return null;
}
// GET /sub-status?email= — read-only subscription state, used by the account
// page to show the "trial cancelled" banner. Returns a member's OWN status.
export async function handleSubStatus(req, env, origin, url) {
  if (!env.STRIPE_SECRET_KEY) return json({ found: false, configured: false }, {}, env, origin);
  const email = String(url.searchParams.get('email') || '').trim().toLowerCase();
  if (!email) return json({ found: false }, {}, env, origin);
  try {
    const sub = await findSubByEmail(env, email);
    if (!sub) return json({ found: false }, {}, env, origin);
    return json({
      found: true, status: sub.status, trialing: sub.status === 'trialing',
      cancel_at_period_end: !!sub.cancel_at_period_end, canceled: sub.status === 'canceled',
      trial_end: sub.trial_end || null, current_period_end: sub.current_period_end || null,
    }, {}, env, origin);
  } catch (e) { return json({ found: false, error: String(e.message || e) }, {}, env, origin); }
}
// GET /trial-eligible?email= — has this email EVER had a subscription (trial or
// paid)? If so they've used their one free trial → not eligible for another.
// Fails open (eligible) so a Stripe hiccup never blocks a genuine new signup.
async function handleTrialEligible(req, env, origin, url) {
  if (!env.STRIPE_SECRET_KEY) return json({ eligible: true, configured: false }, {}, env, origin);
  const email = String(url.searchParams.get('email') || '').trim().toLowerCase();
  if (!email) return json({ eligible: true }, {}, env, origin);
  // Pricing cutover: a returning member whose FIRST subscription was created before
  // this instant is grandfathered onto the legacy $9/$90 no-trial price; anyone who
  // first subscribed on/after keeps the new $15/$150. 1783036800 = 2026-07-03T00:00Z
  // (grandfathers everyone who signed up on/before the 2026-07-02 price change).
  const CUTOVER_TS = 1783036800;
  try {
    let hadTrial = false, earliest = Infinity;
    const custs = await stripeGet(env, '/customers?email=' + encodeURIComponent(email) + '&limit=10');
    for (const c of (custs.data || [])) {
      const subs = await stripeGet(env, '/subscriptions?customer=' + c.id + '&status=all&limit=10');
      for (const s of (subs.data || [])) {
        // Ignore checkouts that never actually started a subscription — an
        // abandoned/failed checkout creates an `incomplete` (then
        // `incomplete_expired`) sub with a Stripe customer, which must NOT burn
        // the one free trial. Only a sub that reached trialing/active/paused/
        // past_due/unpaid/canceled means the trial was genuinely used.
        if (s.status === 'incomplete' || s.status === 'incomplete_expired') continue;
        hadTrial = true;
        if (typeof s.created === 'number' && s.created < earliest) earliest = s.created;
      }
    }
    if (hadTrial) return json({ eligible: false, had_trial: true, grandfathered: earliest < CUTOVER_TS }, {}, env, origin);
    return json({ eligible: true, had_trial: false, grandfathered: false }, {}, env, origin);
  } catch (e) { return json({ eligible: true, error: String(e.message || e) }, {}, env, origin); }
}
// POST /admin/cancel-subscription { email, immediate? } — admin-gated. Sets the
// member's sub to cancel at period end (trial → no charge; paid → keeps paid term).
// Void every OPEN invoice on a customer. Canceling a subscription does NOT
// stop Stripe's dunning on invoices already issued — a past-due member keeps
// getting "payment failed, update your card" retries/emails until the open
// invoice is voided. Best-effort: a restricted key without Invoices:Write
// reports the failure instead of throwing so the cancel itself still lands.
async function voidOpenInvoices(env, customerId) {
  const out = { voided: [], failed: [] };
  if (!customerId) return out;
  try {
    const inv = await stripeGet(env, '/invoices?customer=' + customerId + '&status=open&limit=20');
    for (const i of (inv.data || [])) {
      try {
        const r = await fetch('https://api.stripe.com/v1/invoices/' + i.id + '/void', {
          method: 'POST', headers: { Authorization: 'Bearer ' + stripeWriteKey(env) },
        });
        if (r.ok) out.voided.push(i.id);
        else out.failed.push(i.id + ' (' + r.status + ')');
      } catch (e) { out.failed.push(i.id); }
    }
  } catch (_) { /* listing failed — nothing to void */ }
  return out;
}
// Shared cancel core for the admin + member self-serve endpoints. A sub in
// dunning (past_due/unpaid) always cancels IMMEDIATELY and voids its open
// invoices — "cancel at period end" would leave Stripe retrying the failed
// charge and emailing the member indefinitely (the Sarah Weber case).
async function cancelSubForEmail(env, email, immediate) {
  const sub = await findSubByEmail(env, email);
  if (!sub) return { found: false };
  const dunning = sub.status === 'past_due' || sub.status === 'unpaid';
  if (sub.status === 'canceled') {
    // Already canceled can still have an open invoice mid-dunning — void it.
    const inv = await voidOpenInvoices(env, sub.customer);
    return { found: true, ok: true, status: 'canceled', already: true, invoices: inv };
  }
  const now = immediate || dunning;
  const res = now
    ? await fetch('https://api.stripe.com/v1/subscriptions/' + sub.id, { method: 'DELETE', headers: { Authorization: 'Bearer ' + stripeWriteKey(env) } }).then(r => r.json())
    : await stripePost(env, '/subscriptions/' + sub.id, { cancel_at_period_end: 'true' });
  if (res.error) throw new Error(res.error.message || 'Stripe error');
  const invoices = now ? await voidOpenInvoices(env, sub.customer) : null;
  return {
    found: true, ok: true, status: res.status,
    cancel_at_period_end: !!res.cancel_at_period_end,
    was_trialing: sub.status === 'trialing', was_dunning: dunning,
    invoices,
  };
}
async function handleAdminCancelSub(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.STRIPE_SECRET_KEY) return json({ error: 'Stripe not configured' }, { status: 500 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const email = String(b.email || '').trim().toLowerCase();
  if (!email) return json({ error: 'email required' }, { status: 400 }, env, origin);
  try {
    const r = await cancelSubForEmail(env, email, !!b.immediate);
    if (!r.found) return json({ error: 'No subscription found for ' + email }, { status: 404 }, env, origin);
    return json({ ...r, email }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}
// POST /cancel-my-plan { member_id } — member SELF-SERVE cancel, used by the
// account page when Memberstack's Stripe portal launcher can't help (e.g. a
// past-due member whose plan connection already lapsed — they're stuck getting
// dunning emails with no working cancel path). Authenticated by the opaque
// Memberstack member id from the logged-in session: the worker resolves the
// member's CANONICAL email via the Memberstack Admin API and only ever cancels
// that member's own subscription — no caller-supplied email is trusted.
async function handleCancelMyPlan(req, env, origin) {
  if (!env.STRIPE_SECRET_KEY) return json({ ok: false, error: 'billing not configured' }, { status: 500 }, env, origin);
  if (!env.MEMBERSTACK_SECRET_KEY) return json({ ok: false, error: 'accounts not configured' }, { status: 500 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ ok: false, error: 'bad json' }, { status: 400 }, env, origin); }
  const memberId = String(b.member_id || '').trim();
  if (!memberId) return json({ ok: false, error: 'member_id required' }, { status: 400 }, env, origin);
  try {
    const mr = await fetch(MS_API + '/members/' + encodeURIComponent(memberId), { headers: msHeaders(env) });
    if (!mr.ok) return json({ ok: false, error: 'member not found' }, { status: 404 }, env, origin);
    const mj = await mr.json();
    const m = mj.data || mj;
    const email = String(
      (m.auth && m.auth.email) || m.email ||
      (m.customFields && (m.customFields.email || m.customFields['email-address'])) || ''
    ).trim().toLowerCase();
    if (!email) return json({ ok: false, error: 'no email on account' }, { status: 404 }, env, origin);
    const r = await cancelSubForEmail(env, email, false);
    if (!r.found) return json({ ok: true, found: false, message: 'No subscription to cancel.' }, {}, env, origin);
    return json(r, {}, env, origin);
  } catch (e) { return json({ ok: false, error: String(e.message || e) }, { status: 502 }, env, origin); }
}
// ── Atlas Intelligence — projection store + Pro gate ────────────────────────
// The projection VALUES live only here (D1), never in the public repo or any
// public payload (spec §6: blur is visual, the data must actually be absent).
// Raw inputs include `list_psf_observed` which is INTERNAL-ONLY — the deep
// sanitizer below strips it (and its provenance/basis fields) from every
// response as a belt-and-suspenders guarantee on top of "we never SELECT it".
async function ensureAtlasProjTable(env) {
  if (!env.DB) return;
  try {
    await env.DB.exec(`CREATE TABLE IF NOT EXISTS atlas_projection (slug TEXT PRIMARY KEY, city_slug TEXT, raw_json TEXT NOT NULL, model_json TEXT, confidence TEXT, comp_count INTEGER DEFAULT 0, updated_at INTEGER)`);
  } catch (_) {}
}
const ATLAS_INTERNAL_KEYS = ['list_psf_observed', 'list_psf_source', 'list_psf_basis'];
function atlasSanitize(x) {
  if (Array.isArray(x)) return x.map(atlasSanitize);
  if (x && typeof x === 'object') {
    const out = {};
    for (const k of Object.keys(x)) {
      if (ATLAS_INTERNAL_KEYS.indexOf(k) >= 0) continue;
      out[k] = atlasSanitize(x[k]);
    }
    return out;
  }
  return x;
}
// Server-side Pro check by Memberstack member id — an active or trialing plan
// connection counts as Pro (same rule as the client gate: trialing must not
// be re-popped). Fails CLOSED: no verification → no values.
async function isProMemberServer(env, memberId) {
  if (!env.MEMBERSTACK_SECRET_KEY || !memberId) return false;
  try {
    const r = await fetch(MS_API + '/members/' + encodeURIComponent(memberId), { headers: msHeaders(env) });
    if (!r.ok) return false;
    const j = await r.json();
    const m = j.data || j;
    const pcs = m.planConnections || m.plan_connections || [];
    return Array.isArray(pcs) && pcs.some(pc => {
      if (!pc) return false;
      const st = String(pc.status || '').toUpperCase();
      return pc.active === true || st === 'ACTIVE' || st === 'TRIALING' || st === 'PAST_DUE';
    });
  } catch (_) { return false; }
}
async function atlasProAllowed(req, env, memberId) {
  // Admin token (Studio tooling / verification) also unlocks values.
  try {
    const auth = req.headers.get('Authorization') || '';
    if (env.ADMIN_TOKEN && auth === 'Bearer ' + env.ADMIN_TOKEN) return true;
  } catch (_) {}
  return isProMemberServer(env, memberId);
}
// POST /atlas/projection-full { slug, member_id } → the full Surface A/B
// payload for ONE project, Pro-gated. Public callers get { gated: true } and
// no numbers, ever.
async function handleAtlasProjectionFull(req, env, origin) {
  if (!env.DB) return json({ gated: true, error: 'unavailable' }, { status: 503 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const slug = String(b.slug || '').trim().toLowerCase();
  if (!slug) return json({ error: 'slug required' }, { status: 400 }, env, origin);
  await ensureAtlasProjTable(env);
  if (!(await atlasProAllowed(req, env, String(b.member_id || '').trim()))) {
    return json({ gated: true }, { status: 403 }, env, origin);
  }
  try {
    const row = await env.DB.prepare('SELECT model_json, raw_json, confidence, comp_count, updated_at FROM atlas_projection WHERE slug=?').bind(slug).first();
    if (!row || !row.model_json) return json({ found: false }, {}, env, origin);
    const model = atlasSanitize(JSON.parse(row.model_json));
    // Surface the subject project's own sell-through from the authored research
    // row (pct_sold is never estimated — the backfill drops unsourced values)
    // so the card can show a headline "% sold" for the project itself, not just
    // the comps. Attached after sanitize; it's the same fact the comps expose.
    try {
      const raw = row.raw_json ? JSON.parse(row.raw_json) : null;
      if (raw && typeof raw.pct_sold === 'number') {
        model.pct_sold = raw.pct_sold;
        if (raw.pct_sold_asof) model.pct_sold_asof = String(raw.pct_sold_asof);
      }
    } catch (_) {}
    return json({ found: true, gated: false, slug, model, updated_at: row.updated_at }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}
// POST /atlas/market-band { market, member_id } → submarket median band
// (market pages' aggregated Surface A). Same gate.
async function handleAtlasMarketBand(req, env, origin) {
  if (!env.DB) return json({ gated: true, error: 'unavailable' }, { status: 503 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const market = String(b.market || '').trim().toLowerCase();
  if (!market) return json({ error: 'market required' }, { status: 400 }, env, origin);
  await ensureAtlasProjTable(env);
  if (!(await atlasProAllowed(req, env, String(b.member_id || '').trim()))) {
    return json({ gated: true }, { status: 403 }, env, origin);
  }
  try {
    // Boroughs fold into their parent market (the Atlas groups Brooklyn under
    // New York City) — the median must cover the same set the client displays.
    const MKT_PARTS = { 'new-york-city': ['new-york-city', 'brooklyn', 'manhattan', 'queens'] };
    const keys = MKT_PARTS[market] || [market];
    const rs = await env.DB.prepare(`SELECT slug, model_json FROM atlas_projection WHERE city_slug IN (${keys.map(() => '?').join(',')}) AND model_json IS NOT NULL`).bind(...keys).all();
    const rows = (rs.results || []).map(r => { try { return { slug: r.slug, m: JSON.parse(r.model_json) }; } catch (_) { return null; } }).filter(Boolean);
    if (rows.length < 2) return json({ found: false, projects: rows.length }, {}, env, origin);
    const mids = rows.map(r => r.m.proj_psf_delivery).filter(Number.isFinite).sort((a, b) => a - b);
    const lows = rows.map(r => r.m.proj_psf_band && r.m.proj_psf_band[0]).filter(Number.isFinite).sort((a, b) => a - b);
    const highs = rows.map(r => r.m.proj_psf_band && r.m.proj_psf_band[1]).filter(Number.isFinite).sort((a, b) => a - b);
    const med = (xs) => xs.length ? (xs.length % 2 ? xs[(xs.length - 1) / 2] : (xs[xs.length / 2 - 1] + xs[xs.length / 2]) / 2) : null;
    return json(atlasSanitize({
      found: true, gated: false, market,
      projects: rows.length,
      median_psf: Math.round(med(mids) / 10) * 10,
      band: [Math.round(med(lows) / 10) * 10, Math.round(med(highs) / 10) * 10],
      proj_psf_source: 'modeled',
    }), {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}
// POST /admin/atlas/projection — upsert one project's raw+model rows (the
// weekly sweep's write path). GET /admin/atlas/coverage — review report.
async function handleAdminAtlasUpsert(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.DB) return json({ error: 'no DB' }, { status: 500 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const slug = String(b.slug || '').trim().toLowerCase();
  if (!slug || !b.raw) return json({ error: 'slug + raw required' }, { status: 400 }, env, origin);
  await ensureAtlasProjTable(env);
  try {
    await env.DB.prepare('INSERT INTO atlas_projection (slug, city_slug, raw_json, model_json, confidence, comp_count, updated_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(slug) DO UPDATE SET city_slug=excluded.city_slug, raw_json=excluded.raw_json, model_json=excluded.model_json, confidence=excluded.confidence, comp_count=excluded.comp_count, updated_at=excluded.updated_at')
      .bind(slug, String(b.city_slug || ''), JSON.stringify(b.raw), b.model ? JSON.stringify(b.model) : null,
            String(b.confidence || ''), Number(b.comp_count || 0), Math.floor(Date.now() / 1000)).run();
    return json({ ok: true, slug }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}
async function handleAdminAtlasCoverage(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.DB) return json({ error: 'no DB' }, { status: 500 }, env, origin);
  await ensureAtlasProjTable(env);
  try {
    const rs = await env.DB.prepare('SELECT slug, city_slug, confidence, comp_count, updated_at, model_json IS NOT NULL AS has_model FROM atlas_projection ORDER BY city_slug, slug').all();
    return json({ rows: rs.results || [] }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}

// GET /admin/member-history?email= — the member's full Stripe billing story:
// every subscription they've ever had (including incomplete checkouts) plus
// recent invoices. Rendered by the Analytics profile modal's "Account history"
// section — the plan pill only shows the CURRENT state, which reads "free" for
// someone whose trial/Pro lapsed and hides that they ever subscribed.
// POST /answer-web { q } — Onyx's BEYOND-THE-DATABASE fallback. When the
// client-side search finds nothing in our corpus, it calls this instead of
// showing "nothing matched": Claude answers from live web search in TMW's
// voice, clearly framed as outside our tracked coverage. Cached 6h per query.
async function handleAnswerWeb(req, env, origin) {
  if (!env.ANTHROPIC_API_KEY) return json({ answer: null, reason: 'unconfigured' }, {}, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const q = String(b.q || '').trim().slice(0, 300);
  if (!q) return json({ answer: null }, {}, env, origin);
  // Thread context — a zero-match query is often a FOLLOW-UP whose subject
  // lives in the prior turns ("whats the total unit count" after a West Palm
  // Beach question). Carry the place + recent turns so the web answer resolves
  // the reference instead of asking the user to clarify.
  const hist = Array.isArray(b.history)
    ? b.history.slice(-3).map(t => ({ q: String((t && t.q) || '').slice(0, 200), answer: String((t && t.answer) || '').slice(0, 1200) })).filter(t => t.q && t.answer)
    : [];
  const place = String(b.place || '').trim().slice(0, 80);
  const sig = await sha256Hex('answerweb-v2|' + q.toLowerCase() + '|' + place.toLowerCase() + '|' + (hist.length ? hist[hist.length - 1].q.toLowerCase() : ''));
  const cacheKey = new Request('https://answerweb.tmw.internal/' + sig, { method: 'GET' });
  const cache = caches.default;
  const reply = (bodyStr) => new Response(bodyStr, {
    status: 200, headers: { 'Content-Type': 'application/json; charset=utf-8', ...corsHeaders(env, origin) },
  });
  try { const hit = await cache.match(cacheKey); if (hit) return reply(await hit.text()); } catch (_) {}
  const SYS = 'You are Onyx, the real-estate intelligence engine for Markets of Tomorrow (a luxury hospitality and development publication). '
    + 'The user searched our database and nothing matched, so answer from web search instead. '
    + 'Be concise: 2-4 sentences, under 110 words, plain prose (no headers, no bullet lists, no markdown). '
    + 'American English, imperial units. Never use em dashes. '
    + 'If the query is about a real project, developer, market or trend, give the most useful current facts. '
    + 'If the query is unanswerable or nonsensical, say so briefly and suggest asking about a project, firm or city instead. '
    + 'Do not fabricate specifics you did not find.'
    + (place || hist.length
      ? ' This is a CONTINUING conversation. Resolve vague references (the pipeline, total units, there, that market) against the prior turns'
        + (place ? ' - the conversation is about ' + place + '.' : '.')
        + ' Never ask the user to clarify which market they mean when the prior turns already name it.'
      : '');
  let out = { answer: null, sources: [] };
  try {
    const ctrl = new AbortController();
    const to = setTimeout(() => ctrl.abort(), 25000);
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST', signal: ctrl.signal,
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: SMART_ANSWER_MODEL, max_tokens: 700, system: SYS,
        tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 3 }],
        messages: hist.length
          ? hist.flatMap(t => [{ role: 'user', content: t.q }, { role: 'assistant', content: t.answer }]).concat([{ role: 'user', content: q }])
          : [{ role: 'user', content: q }],
      }),
    });
    clearTimeout(to);
    if (resp.ok) {
      const data = await resp.json();
      const texts = [], srcs = [];
      for (const blk of (data.content || [])) {
        if (blk.type === 'text') {
          texts.push(blk.text);
          for (const c of (blk.citations || [])) {
            if (c && c.url && !srcs.some(s => s.url === c.url)) srcs.push({ url: c.url, title: c.title || '' });
          }
        }
      }
      const answer = texts.join('').trim();
      if (answer) out = { answer, sources: srcs.slice(0, 4) };
    }
  } catch (_) { /* fall through with null answer */ }
  const bodyStr = JSON.stringify(out);
  try {
    if (out.answer) {
      await cache.put(cacheKey, new Response(bodyStr, { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'public, max-age=21600' } }));
      logIntelAnswer(env, q, out.answer, 'web-fallback');
    }
  } catch (_) {}
  return reply(bodyStr);
}

export async function handleAdminMemberHistory(req, env, origin, url) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.STRIPE_SECRET_KEY) return json({ configured: false, subs: [], invoices: [] }, {}, env, origin);
  const email = String(url.searchParams.get('email') || '').trim().toLowerCase();
  if (!email) return json({ error: 'email required' }, { status: 400 }, env, origin);
  try {
    const subs = [], invoices = [];
    const custs = await stripeGet(env, '/customers?email=' + encodeURIComponent(email) + '&limit=10');
    for (const c of (custs.data || [])) {
      const ss = await stripeGet(env, '/subscriptions?customer=' + c.id + '&status=all&limit=20');
      for (const s of (ss.data || [])) {
        const price = s.items && s.items.data && s.items.data[0] && s.items.data[0].price;
        subs.push({
          id: s.id, status: s.status, created: s.created,
          trial_start: s.trial_start || null, trial_end: s.trial_end || null,
          cancel_at_period_end: !!s.cancel_at_period_end,
          canceled_at: s.canceled_at || null, ended_at: s.ended_at || null,
          current_period_end: s.current_period_end || null,
          amount: price ? price.unit_amount : null,
          interval: price && price.recurring ? price.recurring.interval : null,
        });
      }
      const inv = await stripeGet(env, '/invoices?customer=' + c.id + '&limit=30');
      for (const i of (inv.data || [])) {
        invoices.push({
          id: i.id, created: i.created, status: i.status,          // open|paid|uncollectible|void|draft
          amount_due: i.amount_due, amount_paid: i.amount_paid,
          attempt_count: i.attempt_count || 0,
          next_payment_attempt: i.next_payment_attempt || null,
          billing_reason: i.billing_reason || null,
        });
      }
    }
    subs.sort((a, b) => b.created - a.created);
    invoices.sort((a, b) => b.created - a.created);
    return json({ configured: true, found: !!(subs.length || invoices.length), subs, invoices }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}
// Deep-search allowance ledger for one member. Buckets: a rolling monthly free
// tier (DEEP_MONTHLY_CAP), a permanent credit balance (admin grants + future
// purchases), and an "unlimited" flag (owner/testers). Usage is `intel_deep`
// events tagged in props (extra=credit-spend, unlimited=uncapped); grants are
// `intel_deep_grant` events ({credits:N} and/or {unlimited:bool}).
async function deepStatus(env, member) {
  const cap = DEEP_MONTHLY_CAP;
  let monthlyUsed = 0, granted = 0, extraUsed = 0, unlimited = false;
  if (env.DB && member) {
    const since = Math.floor(Date.now() / 1000) - 30 * 86400;
    try {
      const mu = await env.DB.prepare(
        `SELECT COUNT(*) n FROM events WHERE event_name='intel_deep' AND member_id=? AND ts>=?
           AND (props_json IS NULL OR (props_json NOT LIKE '%"extra":true%' AND props_json NOT LIKE '%"unlimited":true%'))`
      ).bind(member, since).first();
      monthlyUsed = Number(mu && mu.n) || 0;
      const eu = await env.DB.prepare(
        `SELECT COUNT(*) n FROM events WHERE event_name='intel_deep' AND member_id=? AND props_json LIKE '%"extra":true%'`
      ).bind(member).first();
      extraUsed = Number(eu && eu.n) || 0;
      const gr = await env.DB.prepare(
        `SELECT props_json FROM events WHERE event_name='intel_deep_grant' AND member_id=? ORDER BY ts ASC`
      ).bind(member).all();
      for (const row of (gr.results || [])) {
        try {
          const p = JSON.parse(row.props_json || '{}');
          if (typeof p.credits === 'number') granted += p.credits;
          if (typeof p.unlimited === 'boolean') unlimited = p.unlimited;   // latest wins (ASC)
        } catch { /* skip bad row */ }
      }
    } catch { /* best-effort — treat as fresh free tier */ }
  }
  const creditBalance = Math.max(0, granted - extraUsed);
  const freeRemaining = Math.max(0, cap - monthlyUsed);
  const remaining = unlimited ? null : (freeRemaining + creditBalance);
  return { cap, monthlyUsed, granted, extraUsed, creditBalance, unlimited, freeRemaining, remaining };
}

// Account-bound STANDARD (non-deep) intel usage for a non-Pro member — the free
// "taste" quota, enforced SERVER-side (not per-device localStorage) so it can't
// be reset by clearing the browser / going incognito / switching devices.
// Counts `intel_std` events (logged only by /intel-usage below) in a rolling
// 30-day window. Pro members are never counted here (unlimited standard).
async function intelStdStatus(env, member) {
  const cap = FREE_STD_MONTHLY_CAP;
  let used = 0;
  if (env.DB && member) {
    const since = Math.floor(Date.now() / 1000) - 30 * 86400;
    try {
      const r = await env.DB.prepare(
        `SELECT COUNT(*) n FROM events WHERE event_name='intel_std' AND member_id=? AND ts>=?`
      ).bind(member, since).first();
      used = Number(r && r.n) || 0;
    } catch { /* best-effort — treat as fresh */ }
  }
  return { cap, used, remaining: Math.max(0, cap - used) };
}

// GET  /intel-usage?member=&pro=   → { pro, cap, used, remaining } (no consume) —
//                                    the client renders the "N / 5 left" counter
//                                    from this, so it's account-bound on load.
// POST /intel-usage { member, pro } → CONSUME one standard credit. Pro → unlimited
//   (never counted). Non-Pro over cap → { allowed:false, gated:true }. Otherwise
//   logs one `intel_std` event and returns the decremented remaining.
// Pro is asserted by the client (same trust model as the Deep toggle); the point
// here is that the COUNT is server-side and tied to the account.
async function handleIntelUsage(req, env, origin, url) {
  const isPost = req.method === 'POST';
  let member = '', pro = false;
  if (isPost) {
    let b; try { b = await req.json(); } catch { b = {}; }
    member = String(b.member || '').slice(0, 120).trim();
    pro = b.pro === true || b.pro === 'true';
  } else {
    member = String(url.searchParams.get('member') || '').slice(0, 120).trim();
    pro = url.searchParams.get('pro') === 'true' || url.searchParams.get('pro') === '1';
  }
  // Pro members: unlimited standard — never counted, never gated.
  if (pro) return json({ pro: true, cap: FREE_STD_MONTHLY_CAP, used: 0, remaining: null, allowed: true }, {}, env, origin);
  // Only real Memberstack accounts are account-bound; without one we can't key a
  // ledger, so report the full free allowance (the client also gates on signup).
  if (!member || !/^mem_/.test(member)) return json({ pro: false, cap: FREE_STD_MONTHLY_CAP, used: 0, remaining: FREE_STD_MONTHLY_CAP, allowed: true, unkeyed: true }, {}, env, origin);
  const st = await intelStdStatus(env, member);
  if (!isPost) return json({ pro: false, cap: st.cap, used: st.used, remaining: st.remaining, allowed: st.remaining > 0 }, {}, env, origin);
  // POST = consume. Over cap → gate WITHOUT logging (so it stays at 0).
  if (st.remaining <= 0) return json({ pro: false, cap: st.cap, used: st.used, remaining: 0, allowed: false, gated: true }, {}, env, origin);
  try {
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?1,?2,'intel_std',?3)`)
      .bind(Math.floor(Date.now() / 1000), member, JSON.stringify({ used: st.used + 1 })).run();
  } catch (_) { /* best-effort: if the log fails, still allow the answer */ }
  return json({ pro: false, cap: st.cap, used: st.used + 1, remaining: Math.max(0, st.remaining - 1), allowed: true }, {}, env, origin);
}

// ── Map project-open quota (free members) ───────────────────────────────────
// Signed-in FREE members get FREE_MAP_DAILY_CAP project opens per rolling 24h.
// Counting `map_open` events server-side makes the cap ACCOUNT-BOUND: clearing
// localStorage, going incognito, or switching devices can't reset it (the count
// follows the member, not the browser). The project data is already client-side,
// so this can't withhold content — it defeats casual bypass, not a JS editor.
const FREE_MAP_DAILY_CAP = 3;
async function mapDayStatus(env, member) {
  const cap = FREE_MAP_DAILY_CAP;
  let used = 0;
  if (env.DB && member) {
    const since = Math.floor(Date.now() / 1000) - 86400;   // rolling 24h
    try {
      const r = await env.DB.prepare(
        `SELECT COUNT(*) n FROM events WHERE event_name='map_open' AND member_id=? AND ts>=?`
      ).bind(member, since).first();
      used = Number(r && r.n) || 0;
    } catch { /* best-effort — treat as fresh */ }
  }
  return { cap, used, remaining: Math.max(0, cap - used) };
}
// GET  /map-usage?member=&pro=  → { pro, cap, used, remaining, allowed } (no consume)
// POST /map-usage { member, pro } → CONSUME one project open. Pro → unlimited
//   (never counted). Non-Pro over cap → { allowed:false, gated:true }. Otherwise
//   logs one `map_open` event and returns the decremented remaining. Mirrors
//   /intel-usage: the COUNT is server-side and tied to the account.
async function handleMapUsage(req, env, origin, url) {
  const isPost = req.method === 'POST';
  let member = '', pro = false;
  if (isPost) {
    let b; try { b = await req.json(); } catch { b = {}; }
    member = String(b.member || '').slice(0, 120).trim();
    pro = b.pro === true || b.pro === 'true';
  } else {
    member = String(url.searchParams.get('member') || '').slice(0, 120).trim();
    pro = url.searchParams.get('pro') === 'true' || url.searchParams.get('pro') === '1';
  }
  if (pro) return json({ pro: true, cap: FREE_MAP_DAILY_CAP, used: 0, remaining: null, allowed: true }, {}, env, origin);
  if (!member || !/^mem_/.test(member)) return json({ pro: false, cap: FREE_MAP_DAILY_CAP, used: 0, remaining: FREE_MAP_DAILY_CAP, allowed: true, unkeyed: true }, {}, env, origin);
  const st = await mapDayStatus(env, member);
  if (!isPost) return json({ pro: false, cap: st.cap, used: st.used, remaining: st.remaining, allowed: st.remaining > 0 }, {}, env, origin);
  if (st.remaining <= 0) return json({ pro: false, cap: st.cap, used: st.used, remaining: 0, allowed: false, gated: true }, {}, env, origin);
  try {
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?1,?2,'map_open',?3)`)
      .bind(Math.floor(Date.now() / 1000), member, JSON.stringify({ used: st.used + 1 })).run();
  } catch (_) { /* best-effort: if the log fails, still allow the open */ }
  return json({ pro: false, cap: st.cap, used: st.used + 1, remaining: Math.max(0, st.remaining - 1), allowed: true }, {}, env, origin);
}

// POST /design/captions { current, mode, title, slides:[] } → 5 alternative
// carousel SLIDE-HEADLINE options for the Studio design editor. mode 'new' = 5
// fresh fact-based headlines for this slide; 'similar' = 5 rewordings of `current`
// (same meaning, unique phrasing). Fast + cheap (Haiku) for an interactive click.
// Called from the Access-gated Studio; light origin allowlist as a second guard.
async function handleDesignCaptions(req, env, origin) {
  // The Studio calls this through its /api proxy, which may strip Origin/Referer,
  // so allow an empty source; only block a request that arrives WITH a non-admin
  // browser origin (obvious cross-site abuse). Cheap Haiku call, not linked anywhere.
  const src = String(req.headers.get('origin') || req.headers.get('referer') || '');
  if (src && !/(tmw-admin\.pages\.dev|oftmw\.com|localhost|127\.0\.0\.1)/.test(src)) return json({ error: 'forbidden' }, { status: 403 }, env, origin);
  if (!env.ANTHROPIC_API_KEY) return json({ error: 'AI not configured' }, { status: 500 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const mode = b.mode === 'new' ? 'new' : 'similar';   // default: rework the current line
  const current = String(b.current || '').slice(0, 400);
  const title = String(b.title || '').slice(0, 300);
  const slides = Array.isArray(b.slides) ? b.slides.map(s => String(s || '').slice(0, 400)).filter(Boolean).slice(0, 12) : [];
  const exclude = Array.isArray(b.exclude) ? b.exclude.map(s => String(s || '').slice(0, 200)).filter(Boolean).slice(0, 25) : [];
  // Where this slide sits in the deck's arc, so the generator plays the right beat
  // (slide 1 = hook/hype, middle = info, last = close) and reads flowy start to finish.
  const _pi = slides.findIndex(s => s === current);
  const slidePos = _pi >= 0 ? _pi + 1 : slides.length + 1;
  const slideTotal = Math.max(slides.length, slidePos);
  // SHARED BRAIN: same house voice + learned carousel rules the connector/Fable
  // use everywhere else, so captions match the machine's taste and stay unified.
  let brainText = '';
  try { const brain = await assembleBrain(env, { topic: title || current, voice: true, surface: 'carousel', maxKnowledge: 0, maxFacts: 0 }); brainText = (brain && (brain.text || brain.voice)) || ''; } catch (_) {}
  // exclude goes in the USER message (not the cached system block) so "regenerate"
  // gives genuinely fresh options without busting the brain cache.
  const ctx = 'POST: ' + (title || '(untitled)')
    + '\nSLIDE HEADLINES SO FAR:\n' + (slides.length ? slides.map((s, i) => (i + 1) + '. ' + s).join('\n') : '(none)')
    + '\n\nCURRENT SLIDE TEXT:\n' + (current || '(empty)')
    + (exclude.length ? '\n\nALREADY SHOWN, do NOT repeat or closely echo any of these; give genuinely DIFFERENT options:\n' + exclude.map(s => '- ' + s).join('\n') : '');
  const sys = 'You write Instagram carousel SLIDE HEADLINES for Markets of Tomorrow, a real-estate-development media brand.\n\n'
    + (brainText ? ('HOUSE BRAIN (voice + learned rules, FOLLOW THESE):\n' + brainText + '\n\n') : '')
    + 'CAROUSEL ARC (how our decks read start to finish):\n'
    + '- Slide 1 is the HOOK: one bold, high-energy claim that stops the scroll (never a title or label).\n'
    + '- The middle slides deliver the INFO. One concrete fact each, every slide building on the one before so the deck reads in a smooth flow, not disconnected cards.\n'
    + '- The last slide lands the payoff or a light call to action.\n'
    + 'You are writing SLIDE ' + slidePos + ' of ' + slideTotal + '. Make it play its role in that arc and follow naturally from the slide headlines so far.\n\n'
    + 'HARD RULES:\n'
    + '- ONE punchy line per option; lead with a concrete FACT (a number, a name, a superlative) when possible.\n'
    + '- LENGTH: keep each headline TIGHT, roughly 40–80 characters (2–3 short lines in a NARROW slide box). Longer wraps to 5+ lines and crowds the layout.\n'
    + '- PUNCTUATION + CASE: match the CURRENT SLIDE TEXT and the house voice above. No hashtags, no emojis, no clickbait, no em dashes, and no trailing period on a headline unless the house style uses one.\n'
    + '- Preserve exact spellings + diacritics from the post (e.g. "Eudēmonia").\n\n'
    + (mode === 'similar'
        ? 'TASK: REWORD the CURRENT SLIDE TEXT into 5 options, keeping the same meaning + core fact, but each option is a genuinely DIFFERENT phrasing (different structure / word order), clearly the same idea said fresh.'
        : 'TASK: Generate 5 NEW headline ideas for THIS slide, each surfacing a DIFFERENT concrete fact or angle drawn from the post above (do not merely reword the current text).')
    + '\n\nReturn ONLY a JSON array of exactly 5 strings, nothing else.';
  const txt = await fableGenerate(env, { system: sys, user: ctx, maxTokens: 1200 });   // Fable 5 (brain-cached)
  const m = String(txt || '').match(/\[[\s\S]*\]/);
  let arr = []; if (m) { try { arr = JSON.parse(m[0]); } catch (_) {} }
  arr = (Array.isArray(arr) ? arr : []).map(s => String(s || '').trim()).filter(Boolean).slice(0, 5);
  if (!arr.length) return json({ error: 'no options' }, { status: 502 }, env, origin);
  return json({ options: arr }, {}, env, origin);
}

// POST /design/learn { title, slug, slides:[] } → learn from the FINAL, human-
// approved carousel headlines (fired when a design is pushed to Carousels or
// downloaded). Extracts generalizable house-voice lessons and routes them into
// the SHARED brain, so future caption ideas track the team's real taste.
// (Named *Final* to distinguish it from handleDesignLearn further down — the
// /admin/design-learn diff-based learner comparing the AI original against the
// human-edited doc; the two coexist and feed the same brain.)
async function handleDesignFinalLearn(req, env, origin) {
  const src = String(req.headers.get('origin') || req.headers.get('referer') || '');
  if (src && !/(tmw-admin\.pages\.dev|oftmw\.com|localhost|127\.0\.0\.1)/.test(src)) return json({ error: 'forbidden' }, { status: 403 }, env, origin);
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const title = String(b.title || '').slice(0, 300);
  const slug = String(b.slug || '').slice(0, 200);
  const slides = Array.isArray(b.slides) ? b.slides.map(s => String(s || '').slice(0, 400)).filter(Boolean).slice(0, 15) : [];
  if (!env.ANTHROPIC_API_KEY || !env.DB || slides.length < 2) return json({ ok: true, skipped: true }, {}, env, origin);
  try {
    const sys = 'You improve an AI system that writes Instagram CAROUSEL slide headlines for Markets of Tomorrow, a real-estate development media brand. Below are the FINAL, human-approved headlines for one carousel. Extract up to 3 GENERALIZABLE lessons about our caption VOICE, phrasing, length, punctuation, or structure that would make FUTURE AI headlines better — patterns to emulate, NOT one-off facts (ignore specific project names / numbers). If nothing generalizable stands out, return an empty array. Output ONLY a JSON array: [{"type":"voice"|"rule","kind":"like"|"voice"|"structure"|"rule","note":"<short imperative lesson>"}].';
    const usr = 'POST: ' + (title || slug || '(untitled)') + '\n\nFINAL HEADLINES:\n' + slides.map((s, i) => (i + 1) + '. ' + s).join('\n');
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-haiku-4-5', max_tokens: 500, system: sys, messages: [{ role: 'user', content: usr }] }),
    });
    if (!r.ok) return json({ ok: false }, {}, env, origin);
    const d = await r.json();
    const txt = ((d.content || []).find(x => x && x.type === 'text') || {}).text || '';
    const m = txt.match(/\[[\s\S]*\]/); if (!m) return json({ ok: true, learned: 0 }, {}, env, origin);
    let arr; try { arr = JSON.parse(m[0]); } catch { return json({ ok: true, learned: 0 }, {}, env, origin); }
    if (!Array.isArray(arr) || !arr.length) return json({ ok: true, learned: 0 }, {}, env, origin);
    await routeLessons(env, arr, { source: 'design-final:' + String(slug || title).slice(0, 80), evidence: 'Learned from the FINAL approved captions of "' + String(title || slug).slice(0, 80) + '"', injected_ids: [] });
    return json({ ok: true, learned: arr.length }, {}, env, origin);
  } catch (e) { return json({ ok: false, error: String(e.message || e) }, {}, env, origin); }
}

// GET  /admin/deep-credits?member_id=  → that member's deep allowance status.
// POST /admin/deep-credits { member_id, credits?, unlimited? } → grant extra deep
// credits and/or flip the unlimited flag (owner + testers). Admin-gated. Mirrors
// the cancel-subscription control on the member card.
export async function handleAdminDeepCredits(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  if (req.method === 'GET') {
    const member = String(new URL(req.url).searchParams.get('member_id') || '').trim();
    if (!member) return json({ error: 'member_id required' }, { status: 400 }, env, origin);
    return json({ ok: true, member_id: member, ...(await deepStatus(env, member)) }, {}, env, origin);
  }
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const member = String((b && b.member_id) || '').trim();
  if (!member) return json({ error: 'member_id required' }, { status: 400 }, env, origin);
  const props = { by: 'admin' };
  if (typeof b.credits === 'number' && b.credits !== 0) props.credits = Math.round(b.credits);
  if (typeof b.unlimited === 'boolean') props.unlimited = b.unlimited;
  if (!('credits' in props) && !('unlimited' in props)) return json({ error: 'credits (number) or unlimited (bool) required' }, { status: 400 }, env, origin);
  try {
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?,?,?,?)`)
      .bind(Math.floor(Date.now() / 1000), member, 'intel_deep_grant', JSON.stringify(props)).run();
  } catch (e) { return json({ error: String(e.message || e) }, { status: 500 }, env, origin); }
  return json({ ok: true, member_id: member, granted_now: props, ...(await deepStatus(env, member)) }, {}, env, origin);
}

// POST /deep-checkout { member_id, pack } → a Stripe Checkout URL for buying a
// deep-credit pack. Public (a member calls it); the worst a stranger can do is
// PAY to grant someone credits. Credits are granted on the paid return, not here.
async function handleDeepCheckout(req, env, origin) {
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const member = String((b && b.member_id) || '').slice(0, 120).trim();
  const pack = DEEP_PACKS[String((b && b.pack) || '').trim()];
  if (!member || member.indexOf('mem_') !== 0) return json({ error: 'sign in required' }, { status: 401 }, env, origin);
  if (!pack) return json({ error: 'unknown pack' }, { status: 400 }, env, origin);
  const priceId = env[pack.priceEnv];
  if (!priceId) return json({ error: 'pack not configured' }, { status: 503 }, env, origin);
  if (!env.STRIPE_SECRET_KEY) return json({ error: 'stripe not configured' }, { status: 503 }, env, origin);
  // Return the buyer to the exact page they left (the overlay reopens on #search),
  // not a hardcoded page. Only accept an oftmw.com URL; else fall back to the map.
  let base = 'https://www.oftmw.com/map/';
  try {
    const ru = new URL(String((b && b.return_url) || '').slice(0, 600));
    if (/(^|\.)oftmw\.com$/.test(ru.hostname)) {
      ru.searchParams.delete('deep_claim'); ru.searchParams.delete('deep_cancel');
      base = ru.origin + ru.pathname + ru.search;   // drop any prior hash; #search re-added below
    }
  } catch { /* keep the map fallback */ }
  const sep = base.indexOf('?') >= 0 ? '&' : '?';
  try {
    const sess = await stripePost(env, '/checkout/sessions', {
      mode: 'payment',
      'line_items[0][price]': priceId,
      'line_items[0][quantity]': '1',
      client_reference_id: member,
      'metadata[member_id]': member,
      'metadata[credits]': String(pack.credits),
      'metadata[kind]': 'deep_credits',
      success_url: base + sep + 'deep_claim={CHECKOUT_SESSION_ID}#search',
      cancel_url: base + '#search',
    });
    return json({ ok: true, url: sess.url }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}

// POST /deep-claim { session_id } → verify a completed Checkout Session was PAID
// and grant its credits (once). Deduped by session id so a refresh can't double-grant.
async function handleDeepClaim(req, env, origin) {
  let b; try { b = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const sid = String((b && b.session_id) || '').slice(0, 200).trim();
  if (!sid || sid.indexOf('cs_') !== 0) return json({ error: 'bad session' }, { status: 400 }, env, origin);
  if (!env.STRIPE_SECRET_KEY || !env.DB) return json({ error: 'not configured' }, { status: 503 }, env, origin);
  try {
    const sess = await stripeGet(env, '/checkout/sessions/' + encodeURIComponent(sid));
    if (!sess || sess.payment_status !== 'paid') return json({ error: 'not paid', status: sess && sess.payment_status }, { status: 402 }, env, origin);
    const md = sess.metadata || {};
    const member = String(md.member_id || sess.client_reference_id || '').trim();
    const credits = Math.round(Number(md.credits) || 0);
    if (md.kind !== 'deep_credits' || !member || credits < 1) return json({ error: 'not a credit purchase' }, { status: 400 }, env, origin);
    // Dedupe: already claimed this session?
    const dup = await env.DB.prepare(
      `SELECT 1 FROM events WHERE event_name='intel_deep_grant' AND member_id=? AND props_json LIKE ? LIMIT 1`
    ).bind(member, '%"session":"' + sid + '"%').first();
    if (dup) return json({ ok: true, already: true, member_id: member, ...(await deepStatus(env, member)) }, {}, env, origin);
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?,?,?,?)`)
      .bind(Math.floor(Date.now() / 1000), member, 'intel_deep_grant', JSON.stringify({ credits, by: 'purchase', session: sid })).run();
    return json({ ok: true, granted: credits, member_id: member, ...(await deepStatus(env, member)) }, {}, env, origin);
  } catch (e) { return json({ error: String(e.message || e) }, { status: 502 }, env, origin); }
}

function stripePerMonth(amount, interval, count) {
  const c = count || 1;
  if (interval === 'year')  return amount / (12 * c);
  if (interval === 'month') return amount / c;
  if (interval === 'week')  return (amount * 52 / 12) / c;
  if (interval === 'day')   return (amount * 365 / 12) / c;
  return 0;
}
async function fetchStripeIncome(env) {
  let mrr = 0, monthly = 0, yearly = 0, other = 0, paying = 0;
  // Recognized MRR excludes trials (they pay $0 today); trial_mrr is what the
  // current trial cohort WOULD add if it all converts. Kept separate so the chart
  // can add trials as upside without double-counting.
  let mrrActive = 0, payingActive = 0, trialMrr = 0, trialCount = 0, trialNewMrr = 0, trialNewCount = 0;
  // Per-rate breakdown → auto-discovers every price a customer is on (founding
  // $9/mo, $15/mo, annual plans, and any new Memberstack price added later).
  const tierMap = new Map();   // key `${cents}|${interval}|${count}|${cur}` → tier
  const currencies = new Set();
  // Per-sub ledger { created, perMonth } for reconstructing historical MRR + the
  // recent growth rate straight from Stripe (no prior snapshots needed).
  const subLedger = [];
  // Active subscriptions → MRR + cadence split.
  const trialStarts = [];   // new trial signups → activity feed (no charge exists yet)
  let after = null, guard = 0;
  do {
    // status=all (not just 'active') so 14-day-TRIAL subscribers — status
    // 'trialing' — are counted too. New Pro plans launched with a free trial
    // create trialing subs that the old status=active query dropped entirely,
    // so they stayed invisible on the analytics Pro tab for the whole trial.
    // expand customer so trial signups can be named in the activity feed.
    const page = await stripeGet(env, '/subscriptions?status=all&limit=100&expand[]=data.items.data.price&expand[]=data.customer' + (after ? '&starting_after=' + after : ''));
    for (const sub of (page.data || [])) {
      // Count current subscribers: active + trialing (committed, card on file).
      // Skip canceled / incomplete / incomplete_expired / unpaid.
      if (sub.status !== 'active' && sub.status !== 'trialing') continue;
      paying++;
      const isTrial = sub.status === 'trialing';
      let subBucket = null, subAmt = 0, subCur = 'usd', subPerMonth = 0, subIv = null, subIvc = 1;
      for (const it of (sub.items && sub.items.data || [])) {
        const price = it.price || {};
        const amt = (price.unit_amount || 0) / 100 * (it.quantity || 1);
        subAmt += amt; subCur = (price.currency || 'usd').toLowerCase();
        currencies.add(subCur);
        const iv = price.recurring && price.recurring.interval;
        const ivc = (price.recurring && price.recurring.interval_count) || 1;
        subIv = iv; subIvc = ivc;   // primary cadence (Pro plans are single-item)
        const pm = stripePerMonth(amt, iv, ivc);
        mrr += pm; subPerMonth += pm;
        if (iv === 'year') subBucket = 'yearly'; else if (iv === 'month' && subBucket !== 'yearly') subBucket = 'monthly';
      }
      // Recognized (paying) vs trial split. MRR, cadence counts, and the historical
      // ledger are PAYING-ONLY — trials pay $0 today, so they're not recognized
      // revenue. Their committed value lives in trial_mrr as separate upside.
      if (isTrial) {
        trialMrr += subPerMonth; trialCount++;
        // Current-lineup trials only ($32/mo or $300/yr) — older-lineup trials
        // ($9/$90, $15/$150) must not drag the forward per-sub value down.
        if ((subIv === 'month' && Math.round(subAmt) === 32) || (subIv === 'year' && Math.round(subAmt) === 300)) {
          trialNewMrr += subPerMonth; trialNewCount++;
        }
      }
      else {
        mrrActive += subPerMonth; payingActive++;
        if (subBucket === 'yearly') yearly++; else if (subBucket === 'monthly') monthly++; else other++;
        subLedger.push({ created: sub.created || 0, perMonth: subPerMonth });
      }
      // Per-rate tier: group by the exact recurring price. active = paying at this
      // rate, trialing = on trial at this rate, mrr = recognized monthly from it.
      const tkey = `${Math.round(subAmt * 100)}|${subIv || '?'}|${subIvc}|${subCur}`;
      let tier = tierMap.get(tkey);
      if (!tier) { tier = { amount: Math.round(subAmt * 100) / 100, interval: subIv, interval_count: subIvc, currency: subCur, per_month: Math.round(subPerMonth * 100) / 100, active: 0, trialing: 0, mrr: 0 }; tierMap.set(tkey, tier); }
      if (isTrial) tier.trialing++; else { tier.active++; tier.mrr = Math.round((tier.mrr + subPerMonth) * 100) / 100; }
      // A trial sub has no Stripe charge yet ($0), so it never reaches the
      // charge-based feed below. Capture it as a "started trial" activity item.
      if (sub.status === 'trialing') {
        const cust = (sub.customer && typeof sub.customer === 'object') ? sub.customer : {};
        trialStarts.push({
          name: String(cust.name || '').trim(),
          email: String(cust.email || '').trim(),
          amount: 0,            // $0 during trial — the real monthly/annual charge
          currency: subCur,     // lands in the charge-based feed when the first payment goes through
          created: sub.created,
          trial: true,
        });
      }
    }
    after = page.has_more ? page.data[page.data.length - 1].id : null;
  } while (after && ++guard < 50);

  // Succeeded charges → actual collected revenue (gross) + Stripe fees, so we can
  // show revenue (before fees) and income (after fees). Expand the balance
  // transaction to read the processing fee Stripe took on each charge.
  const yearStart = Math.floor(Date.UTC(new Date().getUTCFullYear(), 0, 1) / 1000);
  let allTime = 0, allFee = 0, yearInc = 0, yearFee = 0, after2 = null, cg = 0, truncated = false;
  const purchases = [];                 // most-recent succeeded charges (who + when)
  const PURCHASES_MAX = 25;
  do {
    const page = await stripeGet(env, '/charges?limit=100&expand[]=data.balance_transaction' + (after2 ? '&starting_after=' + after2 : ''));
    for (const c of (page.data || [])) {
      if (c.status !== 'succeeded' || !c.paid) continue;
      const gross = ((c.amount || 0) - (c.amount_refunded || 0)) / 100;   // revenue (customer paid, less refunds)
      const fee = ((c.balance_transaction && c.balance_transaction.fee) || 0) / 100;
      allTime += gross; allFee += fee;
      if (c.created >= yearStart) { yearInc += gross; yearFee += fee; }
      // Activity feed: capture who paid + when, newest first (charges list is
      // already date-desc). Name/email come from billing_details + receipt_email,
      // which are default charge fields — no `expand` needed, so this adds no
      // latency to the existing charge pull.
      if (purchases.length < PURCHASES_MAX) {
        const bd = c.billing_details || {};
        purchases.push({
          name: (bd.name || '').trim(),
          email: (bd.email || c.receipt_email || '').trim(),
          amount: Math.round((c.amount || 0) / 100 * 100) / 100,
          refunded: !!c.refunded || (c.amount_refunded || 0) > 0,
          currency: (c.currency || 'usd').toLowerCase(),
          created: c.created,
        });
      }
    }
    after2 = page.has_more ? page.data[page.data.length - 1].id : null;
    if (++cg >= 30) { truncated = !!after2; break; }
  } while (after2);
  const feeRate = allTime > 0 ? allFee / allTime : 0;   // effective fee % (for netting the run-rate)

  // ── Historical MRR + growth rate (reconstructed from the sub ledger) ──
  // MRR at a past month = sum of per-month value for every currently-active sub
  // that already existed then (their Stripe `created` date). This traces how the
  // CURRENT book of recurring revenue built up — the honest "past" for the chart.
  // Growth = paying subs + MRR added over the trailing window, per week.
  const nowSec = Math.floor(Date.now() / 1000);
  const MONTH = 2629800, WEEK = 604800, HIST_MONTHS = 6, GROW_WEEKS = 8;
  const history = [];
  for (let k = HIST_MONTHS; k >= 0; k--) {
    const t = nowSec - k * MONTH;
    let m = 0;
    for (const s of subLedger) if (s.created && s.created <= t) m += s.perMonth;
    history.push({ ts: t, mrr: Math.round(m * 100) / 100 });
  }
  const growCut = nowSec - GROW_WEEKS * WEEK;
  let recentSubs = 0, recentMrr = 0;
  for (const s of subLedger) if (s.created && s.created >= growCut) { recentSubs++; recentMrr += s.perMonth; }
  // Forward-looking per-sub value: FUTURE signups land at CURRENT pricing, so
  // the projection slope should not inherit the legacy $9/$90 average. Value
  // new subs at the mean perMonth of subs created since the 2026-07 price
  // cutover (>=2 samples), falling back to the trailing-window average.
  const PRICE_CUTOVER = Date.parse('2026-07-01T00:00:00Z') / 1000;
  let ncSubs = 0, ncMrr = 0;
  for (const s of subLedger) if (s.created && s.created >= PRICE_CUTOVER) { ncSubs++; ncMrr += s.perMonth; }
  // Forward per-sub value = the CURRENT price lineup only: average of trials
  // on $32/mo or $300/yr (real plan choices at today's prices). With none in
  // flight, assume list monthly ($32). Older-lineup trials never count.
  const newSubMrr = trialNewCount >= 1 ? trialNewMrr / trialNewCount : 32;
  const growth = {
    window_weeks: GROW_WEEKS,
    subs_per_week: Math.round(recentSubs / GROW_WEEKS * 100) / 100,
    mrr_per_week: Math.round(recentMrr / GROW_WEEKS * 100) / 100,
    new_sub_mrr: Math.round(newSubMrr * 100) / 100,
    // slope for projections: signups/week valued at current pricing
    mrr_per_week_forward: Math.round((recentSubs / GROW_WEEKS) * newSubMrr * 100) / 100,
  };

  // Activity feed = succeeded charges + trial signups (which carry no charge),
  // newest first, capped — so a brand-new trial shows up immediately.
  const recentFeed = purchases.concat(trialStarts)
    .sort((a, b) => (b.created || 0) - (a.created || 0))
    .slice(0, PURCHASES_MAX);

  return {
    fees_all_time: Math.round(allFee * 100) / 100,
    fees_year: Math.round(yearFee * 100) / 100,
    fee_rate: Math.round(feeRate * 10000) / 10000,
    all_time_net: Math.round((allTime - allFee) * 100) / 100,
    year_net: Math.round((yearInc - yearFee) * 100) / 100,
    mrr: Math.round(mrrActive * 100) / 100,               // recognized MRR (trials excluded)
    arr: Math.round(mrrActive * 12 * 100) / 100,
    mrr_paying: Math.round(mrrActive * 100) / 100,        // alias, kept for clarity
    trial_mrr: Math.round(trialMrr * 100) / 100,          // upside if the current trial cohort converts
    paying_active: payingActive,                          // truly-paying subs (trials excluded)
    tiers: [...tierMap.values()].sort((a, b) => (b.active + b.trialing) - (a.active + a.trialing) || a.per_month - b.per_month),
    all_time_income: Math.round(allTime * 100) / 100,
    year_income: Math.round(yearInc * 100) / 100,
    paying_subscribers: payingActive,                     // headline "active subs" = paying only
    monthly_subscriptions: monthly,
    yearly_subscriptions: yearly,
    other_subscriptions: other,
    currency: currencies.size === 1 ? [...currencies][0] : (currencies.size ? 'mixed' : 'usd'),
    income_truncated: truncated,
    recent_purchases: recentFeed,
    mrr_history: history,   // [{ts, mrr}] — reconstructed past, oldest→newest, ends at now
    growth,                 // { window_weeks, subs_per_week, mrr_per_week }
    trialing: trialStarts.length,   // active free-trial subs (subset of paying)
  };
}

// Weekly snapshot of the live subscription state → `subs_snapshot` events. Unlike
// the Stripe reconstruction (which traces only the CURRENT book, so it's blind to
// churn), these capture the true numbers each week, so real MRR movement — new,
// expansion, AND churn — accrues going forward. Cron fires every minute; this
// self-throttles to ~once a week off the latest snapshot's timestamp.
async function maybeSnapshotSubs(env) {
  if (!env.DB || !env.STRIPE_SECRET_KEY) return;
  try {
    const now = Math.floor(Date.now() / 1000);
    // Only consider v2 (recognized-MRR) snapshots for throttling, so the recognized
    // series starts on the next cron instead of waiting a week off the legacy v1 row.
    const last = await env.DB.prepare("SELECT ts FROM events WHERE event_name='subs_snapshot' AND json_extract(props_json,'$.v') >= 2 ORDER BY ts DESC LIMIT 1").first();
    if (last && last.ts && (now - last.ts) < 7 * 86400 - 3600) return;   // ~weekly
    const s = await fetchStripeIncome(env);
    await env.DB.prepare("INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?,?,?,?)")
      .bind(now, 'system:subs-snapshot', 'subs_snapshot', JSON.stringify({
        v: 2,   // v2 = recognized MRR (trials excluded); v1 legacy snapshots are ignored on read
        mrr: s.mrr, arr: s.arr, paying: s.paying_subscribers, trial_mrr: s.trial_mrr,
        monthly: s.monthly_subscriptions, yearly: s.yearly_subscriptions, trialing: s.trialing || 0,
      })).run();
  } catch (_) {}
}

