// POST /admin/design-from-post { post_id } — powers the article editor's "Make
// post" button. Builds a carousel DESIGN draft from an article: the article's
// photos become slides, and brand-voice per-slide headlines + an IG caption are
// written from the brand brain. Slides are lightweight { template, _seed } that
// the design editor materializes with its locked templates. Returns { slug }.
async function handleDesignFromPost(req, env, origin) {
  const authCheck = await requireAdminToken(req, env, origin);
  if (authCheck) return authCheck;
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  await ensureDesignsTable(env);

  let body;
  try { body = await req.json(); } catch { return json({ error: 'invalid JSON' }, { status: 400 }, env, origin); }
  const postId = String(body.post_id || body.id || '').trim();
  if (!postId) return json({ error: 'post_id required' }, { status: 400 }, env, origin);

  const post = await env.DB.prepare(`SELECT id, slug, title, excerpt, body_html, cover_image FROM posts WHERE id = ?1 LIMIT 1`).bind(postId).first();
  if (!post) return json({ error: 'post not found', post_id: postId }, { status: 404 }, env, origin);

  // Photos: cover + inline <img> in body_html (rewritten to R2), deduped, cap 8.
  const photos = [];
  const pushPhoto = (u) => { u = wixImagesToR2((u || '').trim()); if (u && /^https?:\/\//.test(u) && !photos.includes(u)) photos.push(u); };
  pushPhoto(post.cover_image);
  const bodyR2 = wixImagesToR2(post.body_html || '');
  const imgRe = /<img[^>]+src=["']([^"']+)["']/gi;
  let mm; while ((mm = imgRe.exec(bodyR2)) && photos.length < 8) pushPhoto(mm[1]);

  // Brand brain → carousel + voice guidance. Filter to the CAROUSEL-relevant notes
  // (they get buried if we dump all ~200) plus the voice notes, so the model
  // actually follows TMW's carousel copy rules.
  let carouselGuide = '', voiceGuide = '';
  try {
    const notes = await env.DB.prepare(`SELECT kind, category, note FROM brand_notes WHERE active = 1 AND (scope IS NULL OR scope = 'voice') ORDER BY created_at ASC`).all();
    const all = (notes.results || []);
    const isCar = (n) => /carousel|caption|\bslide/i.test((n.category || '') + ' ' + (n.note || ''));
    carouselGuide = all.filter(isCar).map(n => '- ' + n.note).join('\n').slice(0, 5000);
    voiceGuide = all.filter(n => !isCar(n) && /voice|tone|headline|identity|audience/i.test((n.category || '') + ' ' + n.kind + ' ' + (n.note || ''))).map(n => '- ' + n.note).join('\n').slice(0, 2500);
  } catch (_) {}

  // A real carousel even when the article is text-only: with fewer than 4
  // photos, still write a 5-slide story and CYCLE the available photos (the
  // cover repeats; swap images in the editor). Previously a text-first draft
  // produced a single-slide "carousel", which read as a bug from the editor.
  const nSlides = photos.length >= 4 ? photos.length : 5;
  const articleText = String(bodyR2).replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);

  // Generate carousel copy that OBEYS TMW's carousel rules. Falls back to the
  // article's title/excerpt if the model isn't configured/available.
  const MARKETS = ['Florida', 'New York', 'Tennessee', 'Caribbean', 'Rockies', 'Hotels', 'Markets'];
  let gen = null;
  if (env.ANTHROPIC_API_KEY) {
    const sys = 'You are the social copywriter for Markets of Tomorrow (TMW). Write the Instagram CAROUSEL copy for the article below, obeying TMW\'s carousel rules EXACTLY.\n\n'
      + 'TMW CAROUSEL RULES (from the brand brain — non-negotiable):\n' + (carouselGuide || '(none on file)') + '\n\n'
      + 'HARD FORMAT for every slide line you write:\n'
      + '- Each slide is a COMPLETE SENTENCE (subject + verb) that tells a story with specific vivid detail (named materials, scale figures, sensory hooks), NOT a sparse fragment or a stat dump like "860 feet. 52 stories.".\n'
      + '- Slides 2 onward run ~55 to 80 characters (about 2 to 3 lines) — the meaty, information-carrying lines. The text box is NARROW, so anything longer wraps to 5+ lines and crowds the byline; keep each one tight and single-spine.\n'
      + '- Slide 1 is the SHORTEST of all slides (~40 to 60 characters): one punchy, hype, complete-sentence hook, the scroll-stopper.\n'
      + '- ABSOLUTELY NO periods and NO other terminal punctuation on slides. Use COMMAS for rhythm only.\n'
      + '- Each slide is a standalone thought with a single spine (one idea, details as evidence); never repeat the same fact across slides.\n'
      + '- No exact calendar dates or street addresses on SLIDES (soften to a season or "coming soon"); a rough half-year like "early 2027" is fine in the CAPTION. American units and spelling. Positive framing (say what it IS, never what it isn\'t). No em dashes (use a colon or comma). Never invent facts, prices, counts, or names not in the article.\n\n'
      + 'VOICE (accessible luxury, aspirational, hype-but-credible; consumer voice wins over trade):\n' + (voiceGuide || '(write in a confident, insider TMW voice)') + '\n\n'
      + 'CAPTION STRUCTURE (three short paragraphs, complete sentences with periods):\n'
      + '- P1 — lead with the project NAME and a tight descriptor, its status or superlative, and the news/reveal (what just happened). Name the project in the first few words.\n'
      + '- P2 — the specs (height, stories, home size/count) AND the design credits (architect/designer, plus notable context like a firm\'s first US commission). One to two sentences; use the real figures from the article.\n'
      + '- P3 — ONE crisp line on timing + access (showings, completion window).\n'
      + 'Then close with exactly: Explore more with the link in our bio 👉\n\n'
      + 'GOLD-STANDARD CAPTION — match this SHAPE and density (not the specifics):\n'
      + '"262 Fifth Avenue, the ultra-slim NoMad skyscraper, which is now the tallest all-residential tower on Fifth Avenue, has just revealed how it will finish: a gold crown and rooftop infinity pool. '
      + 'At 860 feet and 52 stories, 262 Fifth Avenue is one of the skinniest towers of its height anywhere in New York. The full-floor, column-free homes will average roughly 3,200 square feet, with restrained interiors by Copenhagen\'s Norm Architects and design by Meganom, the firm\'s first American commission. '
      + 'Private showings began this spring, with completion expected in early 2027."\n\n'
      + 'Respond with ONLY JSON:\n'
      + '{"market":"<exactly one of: ' + MARKETS.join(' | ') + '>",'
      + '"location":"<the project CITY for the cover pin, e.g. New York>",'
      + '"caption":"<the IG caption per the structure + gold example above, then the exact bio CTA>",'
      + '"slides":["<slide 1: the shortest hook sentence>","<slide 2 sentence>", ...]}\n'
      + 'Give EXACTLY ' + nSlides + ' slide sentences (one per photo). Do NOT write a tagline or byline — the "MARKETS OF TOMORROW" byline is fixed on the template.';
    const usr = 'Headline: ' + String(post.title || '') + '\n\nArticle:\n' + articleText;
    // Fable 5 for the copy quality (low-volume, quality-critical); Opus 4.8 is the
    // fallback for a safety refusal, an error, or an unusable response. Thinking is
    // always on for Fable 5, so read the TEXT block, not content[0].
    for (const model of ['claude-fable-5', 'claude-opus-4-8']) {
      try {
        const r = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
          body: JSON.stringify({ model, max_tokens: 2500, system: sys, messages: [{ role: 'user', content: usr }] }),
        });
        if (!r.ok) continue;
        const d = await r.json();
        if (d.stop_reason === 'refusal') continue;   // safety refusal → try the fallback model
        const txt = ((d.content || []).find(b => b && b.type === 'text') || {}).text || '';
        const m = txt.match(/\{[\s\S]*\}/);
        if (m) { gen = JSON.parse(m[0]); break; }
      } catch (_) { /* try next model */ }
    }
  }

  const caption = (gen && typeof gen.caption === 'string' && gen.caption.trim())
    ? gen.caption.trim().slice(0, 3000)
    : String(post.excerpt || post.title || '').trim();
  const genLines = (gen && Array.isArray(gen.slides))
    ? gen.slides.map(s => (typeof s === 'string' ? s : (s && s.headline) || ''))
    : [];
  const market   = (gen && MARKETS.includes(gen.market)) ? gen.market : 'Markets';
  const location = String((gen && gen.location) || '').slice(0, 48);

  // Slide 1 = the LOCKED cover template (3-line headline + location pin + market
  // logo). Slides 2+ = a content template that KEEPS the fixed "MARKETS OF
  // TOMORROW" byline — we pass headline ONLY, never tagline (the tagline box IS
  // that byline, so setting it would overwrite the brand line).
  const slides = [];
  for (let i = 0; i < nSlides; i++) {
    const headline = String(genLines[i] || (i === 0 ? (post.title || '') : '')).slice(0, 160);
    // Cycle photos when the article has fewer than the slide count (cover
    // repeats) — an image-less slide still renders with Replace media open.
    const img = photos.length ? photos[i % photos.length] : null;
    if (i === 0) {
      const _seed = { headline };
      if (location) _seed.location = location;
      if (img) _seed.image = img;
      slides.push({ template: 'first_bottom_center', _seed });
    } else {
      const _seed = { headline };
      if (img) _seed.image = img;
      slides.push({ template: 'centered_top', _seed });   // text slides default TOP center (Jake 2026-08-10)
    }
  }

  const ACCT_HANDLE = {
    'Florida': 'floridaoftomorrow', 'New York': 'newyorkoftomorrow', 'Tennessee': 'tennesseeoftomorrow',
    'Caribbean': 'caribbeanoftomorrow', 'Rockies': 'rockiesoftomorrow', 'Hotels': 'hotelsoftomorrow', 'Markets': 'marketsoftomorrow',
  };
  const handle = ACCT_HANDLE[market] || 'marketsoftomorrow';
  const DESIGN_DEFAULT_AVATAR = 'https://media.oftmw.com/wix/ca3b83_0aa909e8efc046dab5ce57c4481ca423~mv2.jpg';
  // doc.market drives the per-market logo lockup on every slide (design editor
  // applies MARKET_LOGOS[market] on load).
  const doc = {
    market,
    caption,
    // Landing link for the carousel distribution (FB/LinkedIn/X/Threads) — the
    // source article's public URL, auto-carried through to the carousel.
    landing_url: post.slug ? ('https://www.oftmw.com/post/' + post.slug + '/') : '',
    account: { handle, name: handle.toUpperCase(), avatar: DESIGN_DEFAULT_AVATAR },
    slides,
    carousel_slug: null,
  };

  const id    = 'dsgn-' + cryptoRandomId(12);
  const now   = Math.floor(Date.now() / 1000);
  const title = ('Post: ' + String(post.title || 'Untitled')).slice(0, 200);
  const slug  = await ensureUniqueDesignSlug(env, slugify(String(post.title || 'post')), null);
  try {
    // ai_original_json = the AI-generated doc (?4) — the "beginning draft" snapshot
    // for the carousel learning loop; diffed against the final at export.
    await env.DB.prepare(
      `INSERT INTO designs (id, slug, title, doc_json, ai_original_json, status, created_at, updated_at)
       VALUES (?1, ?2, ?3, ?4, ?4, 'draft', ?5, ?5)`
    ).bind(id, slug, title, JSON.stringify(doc).slice(0, 2_000_000), now).run();
  } catch (e) {
    return json({ error: 'insert failed', detail: e.message || String(e) }, { status: 500 }, env, origin);
  }
  return json({ ok: true, slug, id, photos: photos.length, ai: !!gen }, {}, env, origin);
}

async function handleDesignsBySlug(req, env, origin, slug) {
  const authCheck = await requireAdminToken(req, env, origin);
  if (authCheck) return authCheck;
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  await ensureDesignsTable(env);
  slug = fullyDecodeSlug(slug);
  const row = await env.DB.prepare(`SELECT * FROM designs WHERE slug = ?1 LIMIT 1`).bind(slug).first();
  if (!row) return json({ error: 'design not found', slug }, { status: 404 }, env, origin);
  return json({ design: rowToDesign(row) }, { headers: { 'Cache-Control': 'no-store' } }, env, origin);
}

async function handleDesignsUpdate(req, env, origin, slug) {
  const authCheck = await requireAdminToken(req, env, origin);
  if (authCheck) return authCheck;
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  await ensureDesignsTable(env);
  slug = fullyDecodeSlug(slug);
  let body;
  try { body = await req.json(); } catch { return json({ error: 'invalid JSON' }, { status: 400 }, env, origin); }
  const existing = await env.DB.prepare(`SELECT * FROM designs WHERE slug = ?1`).bind(slug).first();
  if (!existing) return json({ error: 'design not found', slug }, { status: 404 }, env, origin);
  const sets = [], params = []; let p = 1;
  if ('title'  in body) { sets.push(`title    = ?${p++}`); params.push(String(body.title || 'Untitled design').slice(0, 200)); }
  if ('doc'    in body) {
    const _docStr = JSON.stringify((body.doc && typeof body.doc === 'object') ? body.doc : {}).slice(0, 2_000_000);
    sets.push(`doc_json = ?${p++}`); params.push(_docStr);
    // Snapshot the "beginning draft" baseline on the FIRST meaningful save for
    // EVERY design (not just AI-generated ones), so the carousel learning loop can
    // diff it against the final at export. Only set once (AI designs already have
    // it from design-from-post); captureDesignLesson advances it after each export.
    if (!existing.ai_original_json && designDocText(_docStr).length > 20) {
      sets.push(`ai_original_json = ?${p++}`); params.push(_docStr);
    }
  }
  if ('status' in body) { sets.push(`status   = ?${p++}`); params.push(body.status === 'archived' ? 'archived' : 'draft'); }
  if ('slug'   in body && body.slug && body.slug !== existing.slug) {
    const newSlug = await ensureUniqueDesignSlug(env, body.slug, existing.id);
    sets.push(`slug = ?${p++}`); params.push(newSlug);
  }
  if (!sets.length) return json({ ok: true, design: rowToDesign(existing), note: 'no changes' }, {}, env, origin);
  sets.push(`updated_at = ?${p++}`); params.push(Math.floor(Date.now() / 1000));
  params.push(existing.id);
  await env.DB.prepare(`UPDATE designs SET ${sets.join(', ')} WHERE id = ?${p}`).bind(...params).run();
  const updated = await env.DB.prepare(`SELECT * FROM designs WHERE id = ?1`).bind(existing.id).first();
  return json({ ok: true, design: rowToDesign(updated) }, {}, env, origin);
}

async function handleDesignsDelete(req, env, origin, slug) {
  const authCheck = await requireAdminToken(req, env, origin);
  if (authCheck) return authCheck;
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  await ensureDesignsTable(env);
  slug = fullyDecodeSlug(slug);
  const r = await env.DB.prepare(`DELETE FROM designs WHERE slug = ?1`).bind(slug).run();
  return json({ ok: true, slug, deleted: r.meta && r.meta.changes ? r.meta.changes : 0 }, {}, env, origin);
}

// GET /img?u=<url> — same-origin image proxy with permissive CORS, so the
// Design editor can rasterize R2 photos to PNG via html-to-image without canvas
// tainting (pub-*.r2.dev doesn't send Access-Control-Allow-Origin). Restricted
// to our own image hosts so it can't be used as an open proxy.
async function handleImageProxy(req, env, origin, url) {
  const target = url.searchParams.get('u') || '';
  let u;
  try { u = new URL(target); } catch { return json({ error: 'bad url' }, { status: 400 }, env, origin); }
  const host = u.hostname.toLowerCase();
  const ok = /\.r2\.dev$/.test(host) || /(^|\.)oftmw\.com$/.test(host) || /(^|\.)workers\.dev$/.test(host) || /(^|\.)r2\.cloudflarestorage\.com$/.test(host);
  if (u.protocol !== 'https:' || !ok) return json({ error: 'host not allowed' }, { status: 403 }, env, origin);
  let upstream;
  const range = req.headers.get('range');
  // ?w=<px>(&q=<1-100>) → downscaled thumbnail via Cloudflare Image Resizing.
  const w = parseInt(url.searchParams.get('w') || '', 10);
  const q = parseInt(url.searchParams.get('q') || '', 10);
  const wantResize = !range && w >= 16 && w <= 2000;
  const plainInit = range ? { headers: { Range: range } } : { cf: { cacheTtl: 3600, cacheEverything: true } };
  const resizeInit = { cf: { cacheTtl: 86400, cacheEverything: true, image: { width: w, quality: (q >= 1 && q <= 100) ? q : 74, fit: 'scale-down', format: 'auto' } } };
  try { upstream = await fetch(u.toString(), wantResize ? resizeInit : plainInit); }
  catch (e) { upstream = null; }
  // If resizing failed (e.g. Image Resizing not enabled on the account), fall
  // back to the original so thumbnails never break — strictly no regression.
  if (wantResize && (!upstream || !upstream.ok)) {
    try { upstream = await fetch(u.toString(), { cf: { cacheTtl: 3600, cacheEverything: true } }); }
    catch (e) { upstream = null; }
  }
  if (!upstream) return json({ error: 'fetch failed' }, { status: 502 }, env, origin);
  if (!upstream.ok) return json({ error: 'upstream ' + upstream.status }, { status: upstream.status }, env, origin);
  const ct = upstream.headers.get('content-type') || 'image/jpeg';
  if (!/^(image|video)\//i.test(ct)) return json({ error: 'unsupported content type' }, { status: 415 }, env, origin);
  const h = {
    'Content-Type': ct,
    'Cache-Control': 'public, max-age=86400',
    'Access-Control-Allow-Origin': '*',
    'Cross-Origin-Resource-Policy': 'cross-origin',
  };
  // Pass through range/length so video elements can play + seek the proxied stream.
  const cl = upstream.headers.get('content-length'); if (cl) h['Content-Length'] = cl;
  const ar = upstream.headers.get('accept-ranges'); if (ar) h['Accept-Ranges'] = ar;
  const cr = upstream.headers.get('content-range'); if (cr) h['Content-Range'] = cr;
  return new Response(upstream.body, { status: upstream.status, headers: h });
}

// ─── Cloudflare Stream (video transcode for carousels) ─────────────────────
// Source videos can be huge (e.g. 400MB drone clips) — they can't play for a
// client or fit a carousel. We copy each one into Stream ONCE (server-side,
// from its public R2 URL), which transcodes it into a lightweight adaptive HLS
// stream + thumbnail. Keyed by source URL in stream_videos so a clip is only
// transcoded once. Needs env.CF_ACCOUNT_ID + env.STREAM_API_TOKEN.
async function ensureStreamTable(env) {
  if (!env.DB) return;
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS stream_videos (
    src_url    TEXT PRIMARY KEY,
    uid        TEXT,
    state      TEXT NOT NULL DEFAULT 'queued',
    hls        TEXT,
    thumbnail  TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  )`).run();
}
function streamConfigured(env) { return !!(env.STREAM_API_TOKEN && env.CF_ACCOUNT_ID); }
async function streamApi(env, path, init) {
  const r = await fetch('https://api.cloudflare.com/client/v4/accounts/' + env.CF_ACCOUNT_ID + '/stream' + path,
    Object.assign({}, init, { headers: Object.assign({ 'Authorization': 'Bearer ' + env.STREAM_API_TOKEN }, (init && init.headers) || {}) }));
  let j = null; try { j = await r.json(); } catch (_) {}
  return { ok: r.ok, status: r.status, j };
}
// POST /admin/stream/ensure {url} → copy the source video into Stream (once) and
// return its uid + state. Idempotent: re-ensuring a known URL returns the cached row.
async function handleStreamEnsure(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!streamConfigured(env)) return json({ error: 'Stream not configured (set CF_ACCOUNT_ID + STREAM_API_TOKEN)' }, { status: 503 }, env, origin);
  await ensureStreamTable(env);
  let body = {}; try { body = await req.json(); } catch (_) {}
  const url = String(body.url || '').trim();
  if (!/^https:\/\//.test(url)) return json({ error: 'bad url' }, { status: 400 }, env, origin);
  const existing = await env.DB.prepare(`SELECT * FROM stream_videos WHERE src_url = ?1`).bind(url).first();
  if (existing && existing.uid) return json({ uid: existing.uid, state: existing.state }, {}, env, origin);
  const name = url.split('/').pop().slice(0, 120);
  const { ok, status, j } = await streamApi(env, '/copy', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ url, meta: { name } }) });
  const uid = j && j.result && j.result.uid;
  if (!ok || !uid) return json({ error: 'Stream copy failed', status, detail: (j && j.errors) || null }, { status: 502 }, env, origin);
  const now = Date.now();
  await env.DB.prepare(`INSERT INTO stream_videos (src_url, uid, state, created_at, updated_at) VALUES (?1,?2,?3,?4,?4)
    ON CONFLICT(src_url) DO UPDATE SET uid=?2, state=?3, updated_at=?4`).bind(url, uid, 'queued', now).run();
  return json({ uid, state: 'queued' }, {}, env, origin);
}
// GET /stream-info?uid=<uid> → live transcode state + HLS + thumbnail. PUBLIC
// (the client carousel page polls this); only exposes playback info for a uid.
async function handleStreamInfo(req, env, origin) {
  if (!streamConfigured(env)) return json({ error: 'not configured' }, { status: 503 }, env, origin);
  const uid = (new URL(req.url).searchParams.get('uid') || '').trim();
  if (!/^[a-f0-9]{20,}$/i.test(uid)) return json({ error: 'bad uid' }, { status: 400 }, env, origin);
  const { ok, j } = await streamApi(env, '/' + uid, { method: 'GET' });
  const res = j && j.result;
  if (!ok || !res) return json({ error: 'lookup failed' }, { status: 502 }, env, origin);
  const state = (res.status && res.status.state) || 'queued';
  const hls = (res.playback && res.playback.hls) || '';
  const thumbnail = res.thumbnail || '';
  if (env.DB) { try { await ensureStreamTable(env); await env.DB.prepare(`UPDATE stream_videos SET state=?2, hls=?3, thumbnail=?4, updated_at=?5 WHERE uid=?1`).bind(uid, state, hls, thumbnail, Date.now()).run(); } catch (_) {} }
  return json({ uid, state, ready: state === 'ready', hls, thumbnail }, { headers: { 'Cache-Control': state === 'ready' ? 'public, max-age=300' : 'no-store' } }, env, origin);
}

// ─── Semantic retrieval (TMW Intelligence, grounded) ───────────────────────
// Embeds the project + journal corpus into a Cloudflare Vectorize index so
// Intelligence can RETRIEVE the most relevant projects/articles by meaning, not
// brittle keyword rules. Needs the AI binding (Workers AI embeddings) + a
// VECTORIZE binding named "tmw-knowledge" (768-dim, cosine). Until both bindings
// exist the endpoints return 503 and the client falls back to keyword search.
const EMBED_MODEL = '@cf/baai/bge-base-en-v1.5';   // 768-dim
function retrievalReady(env) { return !!(env && env.AI && env.VECTORIZE); }
async function embedTexts(env, texts) {
  const out = [];
  for (let i = 0; i < texts.length; i += 90) {           // Workers AI batch cap
    const r = await env.AI.run(EMBED_MODEL, { text: texts.slice(i, i + 90) });
    for (const v of (r && r.data) || []) out.push(v);
  }
  return out;
}
function projectText(p) {
  const g = (...k) => { for (const key of k) { const v = p[key]; if (v != null && v !== '') return v; } return ''; };
  const arr = (...k) => { for (const key of k) { const v = p[key]; if (Array.isArray(v) && v.length) return v; if (typeof v === 'string' && v.trim()) return v.split(',').map((s) => s.trim()).filter(Boolean); } return []; };
  const parts = [];
  parts.push(g('Title', 'Name', 'name', 'title'));
  const city = g('City', 'city'), st = g('State', 'state');
  if (city) parts.push('in ' + city + (st ? ', ' + st : ''));
  const types = arr('Types', 'types', 'ProjectType', 'PreferredType');
  if (types.length) parts.push(types.join(', '));
  const status = g('Status', 'status'); if (status) parts.push('status: ' + status);
  const arch = arr('Architects', 'architects'); if (arch.length) parts.push('architect ' + arch.join(', '));
  const dev = arr('Developers', 'developers'); if (dev.length) parts.push('developer ' + dev.join(', '));
  const desc = g('DescriptionLong', 'description_long', 'Description', 'description'); if (desc) parts.push(String(desc));
  return parts.filter(Boolean).join('. ').slice(0, 1600);
}
function slugOf(p) { return String(p.slug || p.Slug || p.id || '').trim(); }
// Vectorize caps ids at 64 bytes — keep "kind:slug" when it fits, else hash the
// slug (cyrb53, deterministic so reindex overwrites rather than duplicating).
function vecId(kind, slug) {
  const id = kind + ':' + slug;
  if (new TextEncoder().encode(id).length <= 64) return id;   // 64-BYTE cap (multibyte-safe)
  let h1 = 0xdeadbeef ^ slug.length, h2 = 0x41c6ce57 ^ slug.length;
  for (let i = 0; i < slug.length; i++) { const c = slug.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return kind + ':' + (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}
// POST /admin/reindex — rebuild the Vectorize index from projects + journal.
async function handleReindex(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!retrievalReady(env)) return json({ error: 'retrieval not configured (need AI + VECTORIZE bindings + the tmw-knowledge index)' }, { status: 503 }, env, origin);
  const stats = await reindexAll(env);
  return json({ ok: true, ...stats }, {}, env, origin);
}
// Runs ~daily from the cron so the index tracks new projects/articles.
async function maybeReindex(env) {
  if (!retrievalReady(env) || !env.DB) return;
  const now = Math.floor(Date.now() / 1000);
  const row = await env.DB.prepare("SELECT value FROM sync_state WHERE key='reindex_at'").first();
  if (row && (now - (parseInt(row.value, 10) || 0)) < 20 * 3600) return;   // ~daily
  await env.DB.prepare("INSERT INTO sync_state (key,value,updated_at) VALUES ('reindex_at',?1,?1) ON CONFLICT(key) DO UPDATE SET value=?1, updated_at=?1").bind(now).run();
  try { await reindexAll(env); } catch (_) {}
}
async function reindexAll(env) {
  const stats = { projects: 0, articles: 0 };
  // 1) Projects — from the public map JSON.
  try {
    const r = await fetch('https://www.oftmw.com/map/projects-flat.json', { cf: { cacheTtl: 30 } });
    const j = await r.json();
    const rows = Array.isArray(j) ? j : (j.projects || j.rows || []);
    const docs = rows.map((p) => ({ slug: slugOf(p), text: projectText(p), p })).filter((d) => d.slug && d.text);
    for (let i = 0; i < docs.length; i += 90) {
      const chunk = docs.slice(i, i + 90);
      const vecs = await embedTexts(env, chunk.map((d) => d.text));
      const items = chunk.map((d, k) => ({ id: vecId('project', d.slug), values: vecs[k], metadata: {
        kind: 'project', slug: d.slug,
        title: String(d.p.Title || d.p.Name || d.p.name || '').slice(0, 200),
        city: String(d.p.City || d.p.city || '').slice(0, 80),
        status: String(d.p.Status || d.p.status || '').slice(0, 40),
      } })).filter((it) => Array.isArray(it.values));
      if (items.length) { await env.VECTORIZE.upsert(items); stats.projects += items.length; }
    }
  } catch (e) { stats.projectsError = String(e && e.message || e); }
  // 2) Journal articles — from the published posts in D1, enriched with the
  // Onyx summary + entities (post_intel) when available so entity/topic queries
  // retrieve them (falls back to title+category+excerpt for un-summarized posts).
  try {
    const r = await env.DB.prepare(`SELECT p.slug, p.title, p.excerpt, p.main_category, pi.tldr, pi.takeaways_json, pi.entities_json
      FROM posts p LEFT JOIN post_intel pi ON pi.slug = p.slug WHERE p.status = 'published' LIMIT 2000`).all();
    const rows = (r.results || []).filter((x) => x.slug);
    for (let i = 0; i < rows.length; i += 90) {
      const chunk = rows.slice(i, i + 90);
      const vecs = await embedTexts(env, chunk.map((x) => articleIntelText(
        x.title, x.main_category, x.excerpt, x.tldr, safeJson(x.takeaways_json, []), safeJson(x.entities_json, {})
      )));
      const items = chunk.map((x, k) => ({ id: vecId('article', x.slug), values: vecs[k], metadata: {
        kind: 'article', slug: String(x.slug).slice(0, 200), title: String(x.title || '').slice(0, 200), tldr: String(x.tldr || '').slice(0, 400),
      } })).filter((it) => Array.isArray(it.values));
      if (items.length) { await env.VECTORIZE.upsert(items); stats.articles += items.length; }
    }
  } catch (e) { stats.articlesError = String(e && e.message || e); }
  return stats;
}

// POST /admin/knowledge — the proactive "Onyx study" routine banks evergreen
// real-estate domain knowledge (term definitions, city profiles, sector trends)
// that Onyx reads as BACKGROUND on every answer. Each note is embedded into the
// same Vectorize index with kind:'knowledge' (one note per topic — re-studying a
// topic upserts/refreshes it). Onyx retrieves the relevant notes per query and
// uses them for expert context, never as a TMW project fact.
async function handleKnowledgeIngest(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin);
  if (denied) return denied;
  if (!retrievalReady(env)) return json({ error: 'retrieval not configured' }, { status: 503 }, env, origin);
  let body; try { body = await req.json(); } catch { return json({ error: 'bad json' }, { status: 400 }, env, origin); }
  const notes = (Array.isArray(body && body.notes) ? body.notes : []).slice(0, 50)
    .map((n) => ({
      topic: String((n && n.topic) || '').trim().slice(0, 120),
      text: String((n && n.text) || '').trim().slice(0, 600),
      source: String((n && n.source) || '').trim().slice(0, 300),
    }))
    .filter((n) => n.topic && n.text.length >= 20);
  if (!notes.length) return json({ error: 'no valid notes (need topic + text>=20 chars)' }, { status: 400 }, env, origin);
  let added = 0;
  try {
    for (let i = 0; i < notes.length; i += 40) {
      const chunk = notes.slice(i, i + 40);
      const vecs = await embedTexts(env, chunk.map((n) => n.topic + ': ' + n.text));
      const items = chunk.map((n, k) => ({
        id: vecId('knowledge', n.topic.toLowerCase()),
        values: vecs[k],
        metadata: { kind: 'knowledge', topic: n.topic, text: n.text, source: n.source, ts: Math.floor(Date.now() / 1000) },
      })).filter((it) => Array.isArray(it.values));
      if (items.length) { await env.VECTORIZE.upsert(items); added += items.length; }
    }
    try {
      await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?1, ?2, ?3, ?4)`)
        .bind(Math.floor(Date.now() / 1000), 'system:onyx-study', 'intel_knowledge',
          JSON.stringify({ added, topics: notes.map((n) => n.topic) })).run();
    } catch (_) { /* logging is best-effort */ }
  } catch (e) { return json({ error: String(e && e.message || e) }, { status: 502 }, env, origin); }
  return json({ ok: true, added }, {}, env, origin);
}

// GET /admin/brain/corpus — the performance-ranked article corpus (body text +
// view counts), so a distiller (or a human) can inspect what we're learning
// house voice FROM. Reads the published posts JOIN post_views. Read-only.
async function handleCorpusRead(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.DB) return json({ error: 'no db' }, { status: 503 }, env, origin);
  const url = new URL(req.url);
  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || '60', 10) || 60, 1), 200);
  const offset = Math.max(parseInt(url.searchParams.get('offset') || '0', 10) || 0, 0);
  const chars = Math.min(Math.max(parseInt(url.searchParams.get('chars') || '2400', 10) || 2400, 200), 8000);
  const order = url.searchParams.get('order') === 'recent' ? 'recent' : 'views';
  const orderSql = order === 'recent'
    ? 'p.published_at DESC'
    : 'COALESCE(pv.views,0)+COALESCE(pv.wix_views,0) DESC, p.published_at DESC';
  try {
    const r = await env.DB.prepare(
      `SELECT p.slug, p.title, p.main_category, p.body_html,
              COALESCE(pv.views,0)+COALESCE(pv.wix_views,0) AS views
       FROM posts p LEFT JOIN post_views pv ON pv.slug = p.slug
       WHERE p.status='published'
       ORDER BY ${orderSql} LIMIT ?1 OFFSET ?2`
    ).bind(limit, offset).all();
    const rows = (r.results || []).map((x) => ({
      slug: x.slug, title: x.title || '', category: x.main_category || '', views: x.views || 0,
      text: htmlToText(x.body_html || '').slice(0, chars),
    })).filter((x) => x.slug && x.text);
    return json({ ok: true, count: rows.length, order, articles: rows }, {}, env, origin);
  } catch (e) { return json({ error: String(e && e.message || e) }, { status: 500 }, env, origin); }
}

// POST /admin/brain/learn-corpus — the corpus distiller. Reads the top-performing
// published articles, extracts wide-scoped HOUSE-VOICE patterns from each batch
// (map), consolidates them into a small durable set (reduce), and writes them into
// the brand brain's POOL voice tier (retrieved by relevance in assembleBrain). This
// is how the brain learns from the thousands of articles we've already published,
// weighted by what actually performed. Dedups against the existing brain (reinforce,
// don't duplicate). Body: { top?, batch?, review? }. review=true stages proposals
// in the Teach tab instead of writing straight to pool. Best-effort; bounded so it
// completes in one request (default top=48 → 4 map calls + 1 reduce).
async function handleLearnCorpus(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.ANTHROPIC_API_KEY) return json({ error: 'no anthropic key' }, { status: 503 }, env, origin);
  if (!retrievalReady(env)) return json({ error: 'retrieval not configured (need AI + VECTORIZE)' }, { status: 503 }, env, origin);
  let body = {}; try { body = await req.json(); } catch (_) {}
  const top = Math.min(Math.max(parseInt(body.top, 10) || 48, 10), 120);
  const batchSize = Math.min(Math.max(parseInt(body.batch, 10) || 12, 6), 20);
  const review = body.review === true;   // default false: write straight to POOL (relevance-gated, low risk)
  await ensureBrandNotes(env);

  // 1) Pull the top-performing published articles (by lifetime views).
  let arts = [];
  try {
    const r = await env.DB.prepare(
      `SELECT p.slug, p.title, p.main_category, p.body_html,
              COALESCE(pv.views,0)+COALESCE(pv.wix_views,0) AS views
       FROM posts p LEFT JOIN post_views pv ON pv.slug=p.slug
       WHERE p.status='published'
       ORDER BY COALESCE(pv.views,0)+COALESCE(pv.wix_views,0) DESC, p.published_at DESC
       LIMIT ?1`
    ).bind(top).all();
    arts = (r.results || []).map((x) => ({
      slug: x.slug, title: x.title || '', views: x.views || 0,
      text: htmlToText(x.body_html || '').slice(0, 2200),
    })).filter((x) => x.slug && x.text.length > 200);
  } catch (e) { return json({ error: 'corpus read failed: ' + String(e && e.message || e) }, { status: 500 }, env, origin); }
  if (!arts.length) return json({ error: 'no published articles with body text found' }, { status: 404 }, env, origin);

  // 2-4) MAP → REDUCE → WRITE via the shared distiller.
  const mapSys = 'You study Markets of Tomorrow, a real-estate development media brand, to teach its AI writer the HOUSE VOICE. Below are excerpts from some of TMW\'s BEST-PERFORMING published articles (real, human-approved, high-readership). Extract the DURABLE, WIDE-SCOPED writing patterns they share — tone, sentence rhythm, how openings work, how projects/numbers/places are framed, structural habits, signature moves — that a writer could apply to ANY future article on ANY subject. '
    + 'HARD FILTERS: never output an article-specific fact (a name, price, date, project, city). No one-off observations. Only patterns evidenced across MULTIPLE pieces. Each pattern is ONE short general imperative (e.g. "Open on the concrete change, not a scene-setting metaphor", "Deploy one hard number early to anchor scale"). '
    + 'Output ONLY a JSON array (5-10 items): [{"kind":"voice"|"structure"|"like","note":"<short general imperative>"}].';
  const redSys = 'You are consolidating raw candidate writing-voice patterns for Markets of Tomorrow into the brand brain. Merge duplicates and near-duplicates, drop anything article-specific or too narrow, and return ONLY the DISTINCT, durable, wide-scoped house-voice rules. Aim for 15-25 crisp, non-overlapping imperatives. '
    + 'Output ONLY a JSON array: [{"kind":"voice"|"structure"|"like"|"avoid","note":"<short general imperative>"}].';
  const units = arts.map((a) => ({ label: a.title, weight: a.views, weightLabel: 'views', text: a.text }));
  const res = await distillUnitsToPool(env, units, { mapSys, redSys, source: 'corpus-distill', evidence: "Learned from TMW's top-performing published articles", category: 'corpus', context: 'distilled from top-performing articles', review, batchSize });
  if (!res.candidates) return json({ error: 'extraction produced no candidates' }, { status: 502 }, env, origin);
  try {
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?1,?2,?3,?4)`)
      .bind(Math.floor(Date.now() / 1000), 'system:corpus-distill', 'brain_corpus_learn', JSON.stringify({ scanned: arts.length, candidates: res.candidates, final: res.final, written: res.written, reinforced: res.reinforced, staged: res.staged })).run();
  } catch (_) {}
  return json({ ok: true, scanned: arts.length, candidates: res.candidates, final: res.final, written: res.written, reinforced: res.reinforced, staged: res.staged, review, notes: res.notes }, {}, env, origin);
}

// Shared voice distiller. MAP wide-scoped patterns from `units` (concurrent Haiku
// batches, so a big pass finishes inside one request), REDUCE to a durable set,
// dedup against the brain (reinforce a near-match, don't duplicate), and WRITE to
// the POOL voice tier (or stage for review). units: [{label, weight, weightLabel,
// text}]. Returns { candidates, final, written, reinforced, staged, notes }.
async function distillUnitsToPool(env, units, { mapSys, redSys, source, evidence, category = 'corpus', context = 'distilled', review = false, batchSize = 12 } = {}) {
  const call = async (system, user, maxTokens) => {
    try {
      const r = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        body: JSON.stringify({ model: CLASSIFY_MODEL, max_tokens: maxTokens, system, messages: [{ role: 'user', content: user }] }),
      });
      if (!r.ok) return null;
      const d = await r.json();
      const txt = ((d.content || []).find((b) => b && b.type === 'text') || {}).text || '';
      const m = txt.match(/\[[\s\S]*\]/); if (!m) return null;
      try { return JSON.parse(m[0]); } catch { return null; }
    } catch (_) { return null; }
  };
  // MAP
  const batches = [];
  for (let i = 0; i < units.length; i += batchSize) batches.push(units.slice(i, i + batchSize));
  const mapResults = await Promise.all(batches.map(async (batch) => {
    const usr = batch.map((u, k) => {
      const w = (u.weight != null && u.weight !== '') ? ` (${u.weightLabel || 'signal'}: ${u.weight})` : '';
      return `--- ITEM ${k + 1}${w} — "${String(u.label || '').slice(0, 120)}" ---\n${u.text}`;
    }).join('\n\n').slice(0, 30000);
    const arr = await call(mapSys, usr, 900);
    return Array.isArray(arr) ? arr.filter((c) => c && c.note).map((c) => ({ kind: String(c.kind || 'voice'), note: String(c.note).slice(0, 300) })) : [];
  }));
  const rawCandidates = mapResults.flat();
  if (!rawCandidates.length) return { candidates: 0, final: 0, written: 0, reinforced: 0, staged: 0, notes: [] };
  // REDUCE
  let finalNotes = [];
  const red = await call(redSys, 'CANDIDATES:\n' + rawCandidates.map((c) => `- [${c.kind}] ${c.note}`).join('\n').slice(0, 24000), 1600);
  if (Array.isArray(red)) finalNotes = red.filter((c) => c && c.note).map((c) => ({ kind: String(c.kind || 'voice'), note: String(c.note).slice(0, 400) }));
  if (!finalNotes.length) finalNotes = rawCandidates.slice(0, 24);   // fallback: raw candidates if reduce failed
  finalNotes = finalNotes.slice(0, 30);
  // WRITE
  const ALLOWED = ['like', 'dislike', 'rule', 'voice', 'structure', 'topic', 'avoid', 'example'];
  const now = Math.floor(Date.now() / 1000);
  let written = 0, reinforced = 0, staged = 0; const kept = [];
  for (const n of finalNotes) {
    const note = String(n.note).slice(0, 2000);
    if (!note) continue;
    const kind = ALLOWED.includes(n.kind) ? n.kind : 'voice';
    let existing = null; try { existing = await matchLessonToExisting(env, note); } catch (_) {}
    if (existing && existing.id) {
      try { await env.DB.prepare('UPDATE brand_notes SET violations=COALESCE(violations,0)+1, last_violated_at=?1 WHERE id=?2').bind(now, existing.id).run(); reinforced++; } catch (_) {}
      continue;
    }
    if (review) {
      try { await brainWrite(env, { type: 'voice', kind, note, source, evidence }, { review: true }); staged++; } catch (_) {}
      continue;
    }
    const id = 'bn-' + (crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2));
    try {
      await env.DB.prepare(`INSERT INTO brand_notes (id, kind, category, note, context, created_by, created_at, active, scope, tier, violations) VALUES (?1,?2,?3,?4,?5,?6,?7,1,'voice','pool',0)`)
        .bind(id, kind, category, note, context, source, now).run();
      try { await brainNoteVectors(env, [{ id, kind, note, scope: 'voice' }]); } catch (_) {}
      written++; kept.push({ kind, note });
    } catch (_) {}
  }
  return { candidates: rawCandidates.length, final: finalNotes.length, written, reinforced, staged, notes: kept };
}

// POST /admin/brain/learn-social — distill house voice from our BEST-PERFORMING
// Instagram posts (ranked by saves + shares, the truest "this landed" signal) into
// the brain's POOL voice tier. Reads the ig_posts archive — populate it first with a
// social sync (POST /admin/social/sync, also runs ~daily). Body: { top?, review? }.
async function handleLearnSocial(req, env, origin) {
  const denied = await requireAdminToken(req, env, origin); if (denied) return denied;
  if (!env.ANTHROPIC_API_KEY) return json({ error: 'no anthropic key' }, { status: 503 }, env, origin);
  if (!retrievalReady(env)) return json({ error: 'retrieval not configured (need AI + VECTORIZE)' }, { status: 503 }, env, origin);
  if (!env.DB) return json({ error: 'D1 not configured' }, { status: 500 }, env, origin);
  let body = {}; try { body = await req.json(); } catch (_) {}
  const top = Math.min(Math.max(parseInt(body.top, 10) || 48, 10), 120);
  const review = body.review === true;
  await ensureBrandNotes(env);
  await ensureIgPosts(env);
  // Rank by resonance: saves + shares are the strongest "this landed" signals.
  let rows = [];
  try {
    const r = await env.DB.prepare(
      `SELECT caption, saved, shares, views, reach FROM ig_posts
       WHERE caption IS NOT NULL AND length(caption) > 40
       ORDER BY (COALESCE(saved,0)+COALESCE(shares,0)) DESC, COALESCE(views,0) DESC
       LIMIT ?1`
    ).bind(top).all();
    rows = (r.results || []).filter((x) => x.caption && String(x.caption).length > 40);
  } catch (e) { return json({ error: 'archive read failed: ' + String(e && e.message || e) }, { status: 500 }, env, origin); }
  if (!rows.length) return json({ error: 'no cached posts with captions — run a social sync first (POST /admin/social/sync)' }, { status: 404 }, env, origin);

  const mapSys = 'You study Markets of Tomorrow, a real-estate development media brand, to teach its AI the HOUSE VOICE for social captions. Below are captions from TMW\'s BEST-PERFORMING Instagram posts (highest saves + shares — i.e. what actually resonated). Extract the DURABLE, WIDE-SCOPED caption patterns they share — how the opening hook works, how the subject is framed, sentence/line-break rhythm, how numbers and places are used, CTA and closing habits, emoji/hashtag conventions — that apply to ANY future post on ANY subject. '
    + 'HARD FILTERS: never output a post-specific fact (a name, price, date, project, city, handle). No one-off observations. Only patterns evidenced across MULTIPLE captions. Each pattern is ONE short general imperative (e.g. "Open the caption on the single most surprising fact, not a greeting", "Keep the first line short so it survives the truncation fold"). '
    + 'Output ONLY a JSON array (5-10 items): [{"kind":"voice"|"structure"|"like","note":"<short general imperative>"}].';
  const redSys = 'You are consolidating raw candidate social-caption voice patterns for Markets of Tomorrow. Merge duplicates and near-duplicates, drop anything post-specific or too narrow, and return ONLY the DISTINCT, durable, wide-scoped caption rules. Aim for 12-20 crisp, non-overlapping imperatives. '
    + 'Output ONLY a JSON array: [{"kind":"voice"|"structure"|"like"|"avoid","note":"<short general imperative>"}].';
  const units = rows.map((p) => ({ label: String(p.caption).split('\n')[0].slice(0, 80), weight: (p.saved || 0) + (p.shares || 0), weightLabel: 'saves+shares', text: String(p.caption).slice(0, 1200) }));
  const res = await distillUnitsToPool(env, units, { mapSys, redSys, source: 'social-distill', evidence: 'Learned from top-performing Instagram posts (saves + shares)', category: 'social', context: 'distilled from top-performing IG posts', review, batchSize: 16 });
  if (!res.candidates) return json({ error: 'extraction produced no candidates' }, { status: 502 }, env, origin);
  try {
    await env.DB.prepare(`INSERT INTO events (ts, member_id, event_name, props_json) VALUES (?1,?2,?3,?4)`)
      .bind(Math.floor(Date.now() / 1000), 'system:social-distill', 'brain_social_learn', JSON.stringify({ scanned: rows.length, candidates: res.candidates, final: res.final, written: res.written, reinforced: res.reinforced, staged: res.staged })).run();
  } catch (_) {}
  return json({ ok: true, scanned: rows.length, candidates: res.candidates, final: res.final, written: res.written, reinforced: res.reinforced, staged: res.staged, review, notes: res.notes }, {}, env, origin);
}

// POST /admin/brain/learn-carousels — distill house voice from our carousel
// back-catalog (the Design-editor decks: caption + per-slide headline copy) into
// the brain's POOL voice tier. No engagement metric on designs, so ranked by
// recency + copy-richness. Body: { top?, review? }.
